  if (parser->m_eventPtr && parser->m_eventPtr >= parser->m_positionPtr) {

    XmlUpdatePosition(parser->m_encoding, parser->m_positionPtr, parser->m_eventPtr, &parser->m_position);

    parser->m_positionPtr = parser->m_eventPtr;

