static enum XML_Error

initializeEncoding(XML_Parser parser)

{

  const char *s;

#ifdef XML_UNICODE

  char encodingBuf[128];

  /* See comments abount `protoclEncodingName` in parserInit() */

  if (!parser->m_protocolEncodingName)

    s = NULL;

  else {

    int i;

    for (i = 0; parser->m_protocolEncodingName[i]; i++) {

      if (i == sizeof(encodingBuf) - 1

          || (parser->m_protocolEncodingName[i] & ~0x7f) != 0) {

        encodingBuf[0] = '\0';

        break;

      }

      encodingBuf[i] = (char)parser->m_protocolEncodingName[i];

    }

    encodingBuf[i] = '\0';

    s = encodingBuf;

  }

#else

  s = parser->m_protocolEncodingName;

#endif

  if ((parser->m_ns ? XmlInitEncodingNS : XmlInitEncoding)(&parser->m_initEncoding, &parser->m_encoding, s))

    return XML_ERROR_NONE;

  return handleUnknownEncoding(parser, parser->m_protocolEncodingName);

}



static enum XML_Error

processXmlDecl(XML_Parser parser, int isGeneralTextEntity,

               const char *s, const char *next)

{

  const char *encodingName = NULL;

  const XML_Char *storedEncName = NULL;

  const ENCODING *newEncoding = NULL;

  const char *version = NULL;

  const char *versionend;

  const XML_Char *storedversion = NULL;

  int standalone = -1;

  if (!(parser->m_ns

        ? XmlParseXmlDeclNS

        : XmlParseXmlDecl)(isGeneralTextEntity,

                           parser->m_encoding,

                           s,

                           next,

                           &parser->m_eventPtr,

                           &version,

                           &versionend,

                           &encodingName,

                           &newEncoding,

                           &standalone)) {

    if (isGeneralTextEntity)

      return XML_ERROR_TEXT_DECL;

    else

      return XML_ERROR_XML_DECL;

  }

  if (!isGeneralTextEntity && standalone == 1) {

    parser->m_dtd->standalone = XML_TRUE;

#ifdef XML_DTD

    if (parser->m_paramEntityParsing == XML_PARAM_ENTITY_PARSING_UNLESS_STANDALONE)

      parser->m_paramEntityParsing = XML_PARAM_ENTITY_PARSING_NEVER;

#endif /* XML_DTD */

  }

  if (parser->m_xmlDeclHandler) {

    if (encodingName != NULL) {

      storedEncName = poolStoreString(&parser->m_temp2Pool,

                                      parser->m_encoding,

                                      encodingName,

                                      encodingName

                                      + XmlNameLength(parser->m_encoding, encodingName));

      if (!storedEncName)

              return XML_ERROR_NO_MEMORY;

      poolFinish(&parser->m_temp2Pool);

    }

    if (version) {

      storedversion = poolStoreString(&parser->m_temp2Pool,

                                      parser->m_encoding,

                                      version,

                                      versionend - parser->m_encoding->minBytesPerChar);

      if (!storedversion)

        return XML_ERROR_NO_MEMORY;

    }

    parser->m_xmlDeclHandler(parser->m_handlerArg, storedversion, storedEncName, standalone);

  }

  else if (parser->m_defaultHandler)

    reportDefault(parser, parser->m_encoding, s, next);

  if (parser->m_protocolEncodingName == NULL) {

    if (newEncoding) {

      /* Check that the specified encoding does not conflict with what

       * the parser has already deduced.  Do we have the same number

       * of bytes in the smallest representation of a character?  If

       * this is UTF-16, is it the same endianness?

       */

      if (newEncoding->minBytesPerChar != parser->m_encoding->minBytesPerChar

          || (newEncoding->minBytesPerChar == 2 &&

              newEncoding != parser->m_encoding)) {

        parser->m_eventPtr = encodingName;

        return XML_ERROR_INCORRECT_ENCODING;

      }

      parser->m_encoding = newEncoding;

    }

    else if (encodingName) {

      enum XML_Error result;

      if (!storedEncName) {

        storedEncName = poolStoreString(

          &parser->m_temp2Pool, parser->m_encoding, encodingName,

          encodingName + XmlNameLength(parser->m_encoding, encodingName));

        if (!storedEncName)

          return XML_ERROR_NO_MEMORY;

      }

      result = handleUnknownEncoding(parser, storedEncName);

      poolClear(&parser->m_temp2Pool);

      if (result == XML_ERROR_UNKNOWN_ENCODING)

        parser->m_eventPtr = encodingName;

      return result;

    }

  }



  if (storedEncName || storedversion)

    poolClear(&parser->m_temp2Pool);



  return XML_ERROR_NONE;

}



static enum XML_Error

handleUnknownEncoding(XML_Parser parser, const XML_Char *encodingName)

{

  if (parser->m_unknownEncodingHandler) {

    XML_Encoding info;

    int i;

    for (i = 0; i < 256; i++)

      info.map[i] = -1;

    info.convert = NULL;

    info.data = NULL;

    info.release = NULL;

    if (parser->m_unknownEncodingHandler(parser->m_unknownEncodingHandlerData, encodingName,

                               &info)) {

      ENCODING *enc;

      parser->m_unknownEncodingMem = MALLOC(parser, XmlSizeOfUnknownEncoding());

      if (!parser->m_unknownEncodingMem) {

        if (info.release)

          info.release(info.data);

        return XML_ERROR_NO_MEMORY;

      }

      enc = (parser->m_ns

             ? XmlInitUnknownEncodingNS

             : XmlInitUnknownEncoding)(parser->m_unknownEncodingMem,

                                       info.map,

                                       info.convert,

                                       info.data);

      if (enc) {

        parser->m_unknownEncodingData = info.data;

        parser->m_unknownEncodingRelease = info.release;

        parser->m_encoding = enc;

        return XML_ERROR_NONE;

      }

    }

    if (info.release != NULL)

      info.release(info.data);

  }

  return XML_ERROR_UNKNOWN_ENCODING;

}



static enum XML_Error PTRCALL

prologInitProcessor(XML_Parser parser,

                    const char *s,

                    const char *end,

                    const char **nextPtr)

{

  enum XML_Error result = initializeEncoding(parser);

  if (result != XML_ERROR_NONE)

    return result;

  parser->m_processor = prologProcessor;

  return prologProcessor(parser, s, end, nextPtr);

}



#ifdef XML_DTD



static enum XML_Error PTRCALL

externalParEntInitProcessor(XML_Parser parser,

                            const char *s,

                            const char *end,

                            const char **nextPtr)

{

  enum XML_Error result = initializeEncoding(parser);

  if (result != XML_ERROR_NONE)

    return result;



  /* we know now that XML_Parse(Buffer) has been called,

     so we consider the external parameter entity read */

  parser->m_dtd->paramEntityRead = XML_TRUE;



  if (parser->m_prologState.inEntityValue) {

    parser->m_processor = entityValueInitProcessor;

    return entityValueInitProcessor(parser, s, end, nextPtr);

  }

  else {

    parser->m_processor = externalParEntProcessor;

    return externalParEntProcessor(parser, s, end, nextPtr);

  }

}



static enum XML_Error PTRCALL

entityValueInitProcessor(XML_Parser parser,

                         const char *s,

                         const char *end,

                         const char **nextPtr)

{

  int tok;

  const char *start = s;

  const char *next = start;

  parser->m_eventPtr = start;



  for (;;) {

    tok = XmlPrologTok(parser->m_encoding, start, end, &next);

    parser->m_eventEndPtr = next;

    if (tok <= 0) {

      if (!parser->m_parsingStatus.finalBuffer && tok != XML_TOK_INVALID) {

        *nextPtr = s;

        return XML_ERROR_NONE;

      }

      switch (tok) {

      case XML_TOK_INVALID:

        return XML_ERROR_INVALID_TOKEN;

      case XML_TOK_PARTIAL:

        return XML_ERROR_UNCLOSED_TOKEN;

      case XML_TOK_PARTIAL_CHAR:

        return XML_ERROR_PARTIAL_CHAR;

      case XML_TOK_NONE:   /* start == end */

      default:

        break;

      }

      /* found end of entity value - can store it now */

      return storeEntityValue(parser, parser->m_encoding, s, end);

    }

    else if (tok == XML_TOK_XML_DECL) {

      enum XML_Error result;

      result = processXmlDecl(parser, 0, start, next);

      if (result != XML_ERROR_NONE)

        return result;

      /* At this point, m_parsingStatus.parsing cannot be XML_SUSPENDED.  For that

       * to happen, a parameter entity parsing handler must have

       * attempted to suspend the parser, which fails and raises an

       * error.  The parser can be aborted, but can't be suspended.

       */

      if (parser->m_parsingStatus.parsing == XML_FINISHED)

        return XML_ERROR_ABORTED;

      *nextPtr = next;

      /* stop scanning for text declaration - we found one */

      parser->m_processor = entityValueProcessor;

      return entityValueProcessor(parser, next, end, nextPtr);

    }

    /* If we are at the end of the buffer, this would cause XmlPrologTok to

       return XML_TOK_NONE on the next call, which would then cause the

       function to exit with *nextPtr set to s - that is what we want for other

       tokens, but not for the BOM - we would rather like to skip it;

       then, when this routine is entered the next time, XmlPrologTok will

       return XML_TOK_INVALID, since the BOM is still in the buffer

    */

    else if (tok == XML_TOK_BOM && next == end && !parser->m_parsingStatus.finalBuffer) {

      *nextPtr = next;

      return XML_ERROR_NONE;

    }

    /* If we get this token, we have the start of what might be a

       normal tag, but not a declaration (i.e. it doesn't begin with

       "<!").  In a DTD context, that isn't legal.

    */

    else if (tok == XML_TOK_INSTANCE_START) {

      *nextPtr = next;

      return XML_ERROR_SYNTAX;

    }

    start = next;

    parser->m_eventPtr = start;

  }

}



static enum XML_Error PTRCALL

externalParEntProcessor(XML_Parser parser,

                        const char *s,

                        const char *end,

                        const char **nextPtr)

{

  const char *next = s;

  int tok;



  tok = XmlPrologTok(parser->m_encoding, s, end, &next);

  if (tok <= 0) {

    if (!parser->m_parsingStatus.finalBuffer && tok != XML_TOK_INVALID) {

      *nextPtr = s;

      return XML_ERROR_NONE;

    }

    switch (tok) {

    case XML_TOK_INVALID:

      return XML_ERROR_INVALID_TOKEN;

    case XML_TOK_PARTIAL:

      return XML_ERROR_UNCLOSED_TOKEN;

    case XML_TOK_PARTIAL_CHAR:

      return XML_ERROR_PARTIAL_CHAR;

    case XML_TOK_NONE:   /* start == end */

    default:

      break;

    }

  }

  /* This would cause the next stage, i.e. doProlog to be passed XML_TOK_BOM.

     However, when parsing an external subset, doProlog will not accept a BOM

     as valid, and report a syntax error, so we have to skip the BOM

  */

  else if (tok == XML_TOK_BOM) {

    s = next;

    tok = XmlPrologTok(parser->m_encoding, s, end, &next);

  }



  parser->m_processor = prologProcessor;

  return doProlog(parser, parser->m_encoding, s, end, tok, next,

                  nextPtr, (XML_Bool)!parser->m_parsingStatus.finalBuffer);

}



static enum XML_Error PTRCALL

entityValueProcessor(XML_Parser parser,

                     const char *s,

                     const char *end,

                     const char **nextPtr)

{

  const char *start = s;

  const char *next = s;

  const ENCODING *enc = parser->m_encoding;

  int tok;



  for (;;) {

    tok = XmlPrologTok(enc, start, end, &next);

    if (tok <= 0) {

      if (!parser->m_parsingStatus.finalBuffer && tok != XML_TOK_INVALID) {

        *nextPtr = s;

        return XML_ERROR_NONE;

      }

      switch (tok) {

      case XML_TOK_INVALID:

        return XML_ERROR_INVALID_TOKEN;

      case XML_TOK_PARTIAL:

        return XML_ERROR_UNCLOSED_TOKEN;

      case XML_TOK_PARTIAL_CHAR:

        return XML_ERROR_PARTIAL_CHAR;

      case XML_TOK_NONE:   /* start == end */

      default:

        break;

      }

      /* found end of entity value - can store it now */

      return storeEntityValue(parser, enc, s, end);

    }

    start = next;

  }

}



#endif /* XML_DTD */



static enum XML_Error PTRCALL

prologProcessor(XML_Parser parser,

                const char *s,

                const char *end,

                const char **nextPtr)

{

  const char *next = s;

  int tok = XmlPrologTok(parser->m_encoding, s, end, &next);

  return doProlog(parser, parser->m_encoding, s, end, tok, next,

                  nextPtr, (XML_Bool)!parser->m_parsingStatus.finalBuffer);

}



static enum XML_Error

doProlog(XML_Parser parser,

         const ENCODING *enc,

         const char *s,

         const char *end,

         int tok,

         const char *next,

         const char **nextPtr,

         XML_Bool haveMore)

{

#ifdef XML_DTD

  static const XML_Char externalSubsetName[] = { ASCII_HASH , '\0' };

#endif /* XML_DTD */

  static const XML_Char atypeCDATA[] =

      { ASCII_C, ASCII_D, ASCII_A, ASCII_T, ASCII_A, '\0' };

  static const XML_Char atypeID[] = { ASCII_I, ASCII_D, '\0' };

  static const XML_Char atypeIDREF[] =

      { ASCII_I, ASCII_D, ASCII_R, ASCII_E, ASCII_F, '\0' };

  static const XML_Char atypeIDREFS[] =

      { ASCII_I, ASCII_D, ASCII_R, ASCII_E, ASCII_F, ASCII_S, '\0' };

  static const XML_Char atypeENTITY[] =

      { ASCII_E, ASCII_N, ASCII_T, ASCII_I, ASCII_T, ASCII_Y, '\0' };

  static const XML_Char atypeENTITIES[] = { ASCII_E, ASCII_N,

      ASCII_T, ASCII_I, ASCII_T, ASCII_I, ASCII_E, ASCII_S, '\0' };

  static const XML_Char atypeNMTOKEN[] = {

      ASCII_N, ASCII_M, ASCII_T, ASCII_O, ASCII_K, ASCII_E, ASCII_N, '\0' };

  static const XML_Char atypeNMTOKENS[] = { ASCII_N, ASCII_M, ASCII_T,

      ASCII_O, ASCII_K, ASCII_E, ASCII_N, ASCII_S, '\0' };

  static const XML_Char notationPrefix[] = { ASCII_N, ASCII_O, ASCII_T,

      ASCII_A, ASCII_T, ASCII_I, ASCII_O, ASCII_N, ASCII_LPAREN, '\0' };

  static const XML_Char enumValueSep[] = { ASCII_PIPE, '\0' };

  static const XML_Char enumValueStart[] = { ASCII_LPAREN, '\0' };



  /* save one level of indirection */

  DTD * const dtd = parser->m_dtd;



  const char **eventPP;

  const char **eventEndPP;

  enum XML_Content_Quant quant;



  if (enc == parser->m_encoding) {

    eventPP = &parser->m_eventPtr;

    eventEndPP = &parser->m_eventEndPtr;

  }

  else {

    eventPP = &(parser->m_openInternalEntities->internalEventPtr);

    eventEndPP = &(parser->m_openInternalEntities->internalEventEndPtr);

  }



  for (;;) {

    int role;

    XML_Bool handleDefault = XML_TRUE;

    *eventPP = s;

    *eventEndPP = next;

    if (tok <= 0) {

      if (haveMore && tok != XML_TOK_INVALID) {

        *nextPtr = s;

        return XML_ERROR_NONE;

      }

      switch (tok) {

      case XML_TOK_INVALID:

        *eventPP = next;

        return XML_ERROR_INVALID_TOKEN;

      case XML_TOK_PARTIAL:

        return XML_ERROR_UNCLOSED_TOKEN;

      case XML_TOK_PARTIAL_CHAR:

        return XML_ERROR_PARTIAL_CHAR;

      case -XML_TOK_PROLOG_S:

        tok = -tok;

        break;

      case XML_TOK_NONE:

#ifdef XML_DTD

        /* for internal PE NOT referenced between declarations */

        if (enc != parser->m_encoding && !parser->m_openInternalEntities->betweenDecl) {

          *nextPtr = s;

          return XML_ERROR_NONE;

        }

        /* WFC: PE Between Declarations - must check that PE contains

           complete markup, not only for external PEs, but also for

           internal PEs if the reference occurs between declarations.

        */

        if (parser->m_isParamEntity || enc != parser->m_encoding) {

          if (XmlTokenRole(&parser->m_prologState, XML_TOK_NONE, end, end, enc)

              == XML_ROLE_ERROR)

            return XML_ERROR_INCOMPLETE_PE;

          *nextPtr = s;

          return XML_ERROR_NONE;

        }

#endif /* XML_DTD */

        return XML_ERROR_NO_ELEMENTS;

      default:

        tok = -tok;

        next = end;

        break;

      }

    }

    role = XmlTokenRole(&parser->m_prologState, tok, s, next, enc);

    switch (role) {

    case XML_ROLE_XML_DECL:

      {

        enum XML_Error result = processXmlDecl(parser, 0, s, next);

        if (result != XML_ERROR_NONE)

          return result;

        enc = parser->m_encoding;

        handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_DOCTYPE_NAME:

      if (parser->m_startDoctypeDeclHandler) {

        parser->m_doctypeName = poolStoreString(&parser->m_tempPool, enc, s, next);

        if (!parser->m_doctypeName)

          return XML_ERROR_NO_MEMORY;

        poolFinish(&parser->m_tempPool);

        parser->m_doctypePubid = NULL;

        handleDefault = XML_FALSE;

      }

      parser->m_doctypeSysid = NULL; /* always initialize to NULL */

      break;

    case XML_ROLE_DOCTYPE_INTERNAL_SUBSET:

      if (parser->m_startDoctypeDeclHandler) {

        parser->m_startDoctypeDeclHandler(parser->m_handlerArg, parser->m_doctypeName, parser->m_doctypeSysid,

                                parser->m_doctypePubid, 1);

        parser->m_doctypeName = NULL;

        poolClear(&parser->m_tempPool);

        handleDefault = XML_FALSE;

      }

      break;

#ifdef XML_DTD

    case XML_ROLE_TEXT_DECL:

      {

        enum XML_Error result = processXmlDecl(parser, 1, s, next);

        if (result != XML_ERROR_NONE)

          return result;

        enc = parser->m_encoding;

        handleDefault = XML_FALSE;

      }

      break;

#endif /* XML_DTD */

    case XML_ROLE_DOCTYPE_PUBLIC_ID:

#ifdef XML_DTD

      parser->m_useForeignDTD = XML_FALSE;

      parser->m_declEntity = (ENTITY *)lookup(parser,

                                    &dtd->paramEntities,

                                    externalSubsetName,

                                    sizeof(ENTITY));

      if (!parser->m_declEntity)

        return XML_ERROR_NO_MEMORY;

#endif /* XML_DTD */

      dtd->hasParamEntityRefs = XML_TRUE;

      if (parser->m_startDoctypeDeclHandler) {

        XML_Char *pubId;

        if (!XmlIsPublicId(enc, s, next, eventPP))

          return XML_ERROR_PUBLICID;

        pubId = poolStoreString(&parser->m_tempPool, enc,

                                s + enc->minBytesPerChar,

                                next - enc->minBytesPerChar);

        if (!pubId)

          return XML_ERROR_NO_MEMORY;

        normalizePublicId(pubId);

        poolFinish(&parser->m_tempPool);

        parser->m_doctypePubid = pubId;

        handleDefault = XML_FALSE;

        goto alreadyChecked;

      }

      /* fall through */

    case XML_ROLE_ENTITY_PUBLIC_ID:

      if (!XmlIsPublicId(enc, s, next, eventPP))

        return XML_ERROR_PUBLICID;

    alreadyChecked:

      if (dtd->keepProcessing && parser->m_declEntity) {

        XML_Char *tem = poolStoreString(&dtd->pool,

                                        enc,

                                        s + enc->minBytesPerChar,

                                        next - enc->minBytesPerChar);

        if (!tem)

          return XML_ERROR_NO_MEMORY;

        normalizePublicId(tem);

        parser->m_declEntity->publicId = tem;

        poolFinish(&dtd->pool);

        /* Don't suppress the default handler if we fell through from

         * the XML_ROLE_DOCTYPE_PUBLIC_ID case.

         */

        if (parser->m_entityDeclHandler && role == XML_ROLE_ENTITY_PUBLIC_ID)

          handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_DOCTYPE_CLOSE:

      if (parser->m_doctypeName) {

        parser->m_startDoctypeDeclHandler(parser->m_handlerArg, parser->m_doctypeName,

                                parser->m_doctypeSysid, parser->m_doctypePubid, 0);

        poolClear(&parser->m_tempPool);

        handleDefault = XML_FALSE;

      }

      /* parser->m_doctypeSysid will be non-NULL in the case of a previous

         XML_ROLE_DOCTYPE_SYSTEM_ID, even if parser->m_startDoctypeDeclHandler

         was not set, indicating an external subset

      */

#ifdef XML_DTD

      if (parser->m_doctypeSysid || parser->m_useForeignDTD) {

        XML_Bool hadParamEntityRefs = dtd->hasParamEntityRefs;

        dtd->hasParamEntityRefs = XML_TRUE;

        if (parser->m_paramEntityParsing && parser->m_externalEntityRefHandler) {

          ENTITY *entity = (ENTITY *)lookup(parser,

                                            &dtd->paramEntities,

                                            externalSubsetName,

                                            sizeof(ENTITY));

          if (!entity) {

            /* The external subset name "#" will have already been

             * inserted into the hash table at the start of the

             * external entity parsing, so no allocation will happen

             * and lookup() cannot fail.

             */

            return XML_ERROR_NO_MEMORY; /* LCOV_EXCL_LINE */

          }

          if (parser->m_useForeignDTD)

            entity->base = parser->m_curBase;

          dtd->paramEntityRead = XML_FALSE;

          if (!parser->m_externalEntityRefHandler(parser->m_externalEntityRefHandlerArg,

                                        0,

                                        entity->base,

                                        entity->systemId,

                                        entity->publicId))

            return XML_ERROR_EXTERNAL_ENTITY_HANDLING;

          if (dtd->paramEntityRead) {

            if (!dtd->standalone &&

                parser->m_notStandaloneHandler &&

                !parser->m_notStandaloneHandler(parser->m_handlerArg))

              return XML_ERROR_NOT_STANDALONE;

          }

          /* if we didn't read the foreign DTD then this means that there

             is no external subset and we must reset dtd->hasParamEntityRefs

          */

          else if (!parser->m_doctypeSysid)

            dtd->hasParamEntityRefs = hadParamEntityRefs;

          /* end of DTD - no need to update dtd->keepProcessing */

        }

        parser->m_useForeignDTD = XML_FALSE;

      }

#endif /* XML_DTD */

      if (parser->m_endDoctypeDeclHandler) {

        parser->m_endDoctypeDeclHandler(parser->m_handlerArg);

        handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_INSTANCE_START:

#ifdef XML_DTD

      /* if there is no DOCTYPE declaration then now is the

         last chance to read the foreign DTD

      */

      if (parser->m_useForeignDTD) {

        XML_Bool hadParamEntityRefs = dtd->hasParamEntityRefs;

        dtd->hasParamEntityRefs = XML_TRUE;

        if (parser->m_paramEntityParsing && parser->m_externalEntityRefHandler) {

          ENTITY *entity = (ENTITY *)lookup(parser, &dtd->paramEntities,

                                            externalSubsetName,

                                            sizeof(ENTITY));

          if (!entity)

            return XML_ERROR_NO_MEMORY;

          entity->base = parser->m_curBase;

          dtd->paramEntityRead = XML_FALSE;

          if (!parser->m_externalEntityRefHandler(parser->m_externalEntityRefHandlerArg,

                                        0,

                                        entity->base,

                                        entity->systemId,

                                        entity->publicId))

            return XML_ERROR_EXTERNAL_ENTITY_HANDLING;

          if (dtd->paramEntityRead) {

            if (!dtd->standalone &&

                parser->m_notStandaloneHandler &&

                !parser->m_notStandaloneHandler(parser->m_handlerArg))

              return XML_ERROR_NOT_STANDALONE;

          }

          /* if we didn't read the foreign DTD then this means that there

             is no external subset and we must reset dtd->hasParamEntityRefs

          */

          else

            dtd->hasParamEntityRefs = hadParamEntityRefs;

          /* end of DTD - no need to update dtd->keepProcessing */

        }

      }

#endif /* XML_DTD */

      parser->m_processor = contentProcessor;

      return contentProcessor(parser, s, end, nextPtr);

    case XML_ROLE_ATTLIST_ELEMENT_NAME:

      parser->m_declElementType = getElementType(parser, enc, s, next);

      if (!parser->m_declElementType)

        return XML_ERROR_NO_MEMORY;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_NAME:

      parser->m_declAttributeId = getAttributeId(parser, enc, s, next);

      if (!parser->m_declAttributeId)

        return XML_ERROR_NO_MEMORY;

      parser->m_declAttributeIsCdata = XML_FALSE;

      parser->m_declAttributeType = NULL;

      parser->m_declAttributeIsId = XML_FALSE;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_CDATA:

      parser->m_declAttributeIsCdata = XML_TRUE;

      parser->m_declAttributeType = atypeCDATA;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_ID:

      parser->m_declAttributeIsId = XML_TRUE;

      parser->m_declAttributeType = atypeID;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_IDREF:

      parser->m_declAttributeType = atypeIDREF;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_IDREFS:

      parser->m_declAttributeType = atypeIDREFS;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_ENTITY:

      parser->m_declAttributeType = atypeENTITY;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_ENTITIES:

      parser->m_declAttributeType = atypeENTITIES;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_NMTOKEN:

      parser->m_declAttributeType = atypeNMTOKEN;

      goto checkAttListDeclHandler;

    case XML_ROLE_ATTRIBUTE_TYPE_NMTOKENS:

      parser->m_declAttributeType = atypeNMTOKENS;

    checkAttListDeclHandler:

      if (dtd->keepProcessing && parser->m_attlistDeclHandler)

        handleDefault = XML_FALSE;

      break;

    case XML_ROLE_ATTRIBUTE_ENUM_VALUE:

    case XML_ROLE_ATTRIBUTE_NOTATION_VALUE:

      if (dtd->keepProcessing && parser->m_attlistDeclHandler) {

        const XML_Char *prefix;

        if (parser->m_declAttributeType) {

          prefix = enumValueSep;

        }

        else {

          prefix = (role == XML_ROLE_ATTRIBUTE_NOTATION_VALUE

                    ? notationPrefix

                    : enumValueStart);

        }

        if (!poolAppendString(&parser->m_tempPool, prefix))

          return XML_ERROR_NO_MEMORY;

        if (!poolAppend(&parser->m_tempPool, enc, s, next))

          return XML_ERROR_NO_MEMORY;

        parser->m_declAttributeType = parser->m_tempPool.start;

        handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_IMPLIED_ATTRIBUTE_VALUE:

    case XML_ROLE_REQUIRED_ATTRIBUTE_VALUE:

      if (dtd->keepProcessing) {

        if (!defineAttribute(parser->m_declElementType, parser->m_declAttributeId,

                             parser->m_declAttributeIsCdata, parser->m_declAttributeIsId,

                             0, parser))

          return XML_ERROR_NO_MEMORY;

        if (parser->m_attlistDeclHandler && parser->m_declAttributeType) {

          if (*parser->m_declAttributeType == XML_T(ASCII_LPAREN)

              || (*parser->m_declAttributeType == XML_T(ASCII_N)

                  && parser->m_declAttributeType[1] == XML_T(ASCII_O))) {

            /* Enumerated or Notation type */

            if (!poolAppendChar(&parser->m_tempPool, XML_T(ASCII_RPAREN))

                || !poolAppendChar(&parser->m_tempPool, XML_T('\0')))

              return XML_ERROR_NO_MEMORY;

            parser->m_declAttributeType = parser->m_tempPool.start;

            poolFinish(&parser->m_tempPool);

          }

          *eventEndPP = s;

          parser->m_attlistDeclHandler(parser->m_handlerArg, parser->m_declElementType->name,

                             parser->m_declAttributeId->name, parser->m_declAttributeType,

                             0, role == XML_ROLE_REQUIRED_ATTRIBUTE_VALUE);

          poolClear(&parser->m_tempPool);

          handleDefault = XML_FALSE;

        }

      }

      break;

    case XML_ROLE_DEFAULT_ATTRIBUTE_VALUE:

    case XML_ROLE_FIXED_ATTRIBUTE_VALUE:

      if (dtd->keepProcessing) {

        const XML_Char *attVal;

        enum XML_Error result =

          storeAttributeValue(parser, enc, parser->m_declAttributeIsCdata,

                              s + enc->minBytesPerChar,

                              next - enc->minBytesPerChar,

                              &dtd->pool);

        if (result)

          return result;

        attVal = poolStart(&dtd->pool);

        poolFinish(&dtd->pool);

        /* ID attributes aren't allowed to have a default */

        if (!defineAttribute(parser->m_declElementType, parser->m_declAttributeId,

                             parser->m_declAttributeIsCdata, XML_FALSE, attVal, parser))

          return XML_ERROR_NO_MEMORY;

        if (parser->m_attlistDeclHandler && parser->m_declAttributeType) {

          if (*parser->m_declAttributeType == XML_T(ASCII_LPAREN)

              || (*parser->m_declAttributeType == XML_T(ASCII_N)

                  && parser->m_declAttributeType[1] == XML_T(ASCII_O))) {

            /* Enumerated or Notation type */

            if (!poolAppendChar(&parser->m_tempPool, XML_T(ASCII_RPAREN))

                || !poolAppendChar(&parser->m_tempPool, XML_T('\0')))

              return XML_ERROR_NO_MEMORY;

            parser->m_declAttributeType = parser->m_tempPool.start;

            poolFinish(&parser->m_tempPool);

          }

          *eventEndPP = s;

          parser->m_attlistDeclHandler(parser->m_handlerArg, parser->m_declElementType->name,

                             parser->m_declAttributeId->name, parser->m_declAttributeType,

                             attVal,

                             role == XML_ROLE_FIXED_ATTRIBUTE_VALUE);

          poolClear(&parser->m_tempPool);

          handleDefault = XML_FALSE;

        }

      }

      break;

    case XML_ROLE_ENTITY_VALUE:

      if (dtd->keepProcessing) {

        enum XML_Error result = storeEntityValue(parser, enc,

                                            s + enc->minBytesPerChar,

                                            next - enc->minBytesPerChar);

        if (parser->m_declEntity) {

          parser->m_declEntity->textPtr = poolStart(&dtd->entityValuePool);

          parser->m_declEntity->textLen = (int)(poolLength(&dtd->entityValuePool));

          poolFinish(&dtd->entityValuePool);

          if (parser->m_entityDeclHandler) {

            *eventEndPP = s;

            parser->m_entityDeclHandler(parser->m_handlerArg,

                              parser->m_declEntity->name,

                              parser->m_declEntity->is_param,

                              parser->m_declEntity->textPtr,

                              parser->m_declEntity->textLen,

                              parser->m_curBase, 0, 0, 0);

            handleDefault = XML_FALSE;

          }

        }

        else

          poolDiscard(&dtd->entityValuePool);

        if (result != XML_ERROR_NONE)

          return result;

      }

      break;

    case XML_ROLE_DOCTYPE_SYSTEM_ID:

#ifdef XML_DTD

      parser->m_useForeignDTD = XML_FALSE;

#endif /* XML_DTD */

      dtd->hasParamEntityRefs = XML_TRUE;

      if (parser->m_startDoctypeDeclHandler) {

        parser->m_doctypeSysid = poolStoreString(&parser->m_tempPool, enc,

                                       s + enc->minBytesPerChar,

                                       next - enc->minBytesPerChar);

        if (parser->m_doctypeSysid == NULL)

          return XML_ERROR_NO_MEMORY;

        poolFinish(&parser->m_tempPool);

        handleDefault = XML_FALSE;

      }

#ifdef XML_DTD

      else

        /* use externalSubsetName to make parser->m_doctypeSysid non-NULL

           for the case where no parser->m_startDoctypeDeclHandler is set */

        parser->m_doctypeSysid = externalSubsetName;

#endif /* XML_DTD */

      if (!dtd->standalone

#ifdef XML_DTD

          && !parser->m_paramEntityParsing

#endif /* XML_DTD */

          && parser->m_notStandaloneHandler

          && !parser->m_notStandaloneHandler(parser->m_handlerArg))

        return XML_ERROR_NOT_STANDALONE;

#ifndef XML_DTD

      break;

#else /* XML_DTD */

      if (!parser->m_declEntity) {

        parser->m_declEntity = (ENTITY *)lookup(parser,

                                      &dtd->paramEntities,

                                      externalSubsetName,

                                      sizeof(ENTITY));

        if (!parser->m_declEntity)

          return XML_ERROR_NO_MEMORY;

        parser->m_declEntity->publicId = NULL;

      }

#endif /* XML_DTD */

      /* fall through */

    case XML_ROLE_ENTITY_SYSTEM_ID:

      if (dtd->keepProcessing && parser->m_declEntity) {

        parser->m_declEntity->systemId = poolStoreString(&dtd->pool, enc,

                                               s + enc->minBytesPerChar,

                                               next - enc->minBytesPerChar);

        if (!parser->m_declEntity->systemId)

          return XML_ERROR_NO_MEMORY;

        parser->m_declEntity->base = parser->m_curBase;

        poolFinish(&dtd->pool);

        /* Don't suppress the default handler if we fell through from

         * the XML_ROLE_DOCTYPE_SYSTEM_ID case.

         */

        if (parser->m_entityDeclHandler && role == XML_ROLE_ENTITY_SYSTEM_ID)

          handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_ENTITY_COMPLETE:

      if (dtd->keepProcessing && parser->m_declEntity && parser->m_entityDeclHandler) {

        *eventEndPP = s;

        parser->m_entityDeclHandler(parser->m_handlerArg,

                          parser->m_declEntity->name,

                          parser->m_declEntity->is_param,

                          0,0,

                          parser->m_declEntity->base,

                          parser->m_declEntity->systemId,

                          parser->m_declEntity->publicId,

                          0);

        handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_ENTITY_NOTATION_NAME:

      if (dtd->keepProcessing && parser->m_declEntity) {

        parser->m_declEntity->notation = poolStoreString(&dtd->pool, enc, s, next);

        if (!parser->m_declEntity->notation)

          return XML_ERROR_NO_MEMORY;

        poolFinish(&dtd->pool);

        if (parser->m_unparsedEntityDeclHandler) {

          *eventEndPP = s;

          parser->m_unparsedEntityDeclHandler(parser->m_handlerArg,

                                    parser->m_declEntity->name,

                                    parser->m_declEntity->base,

                                    parser->m_declEntity->systemId,

                                    parser->m_declEntity->publicId,

                                    parser->m_declEntity->notation);

          handleDefault = XML_FALSE;

        }

        else if (parser->m_entityDeclHandler) {

          *eventEndPP = s;

          parser->m_entityDeclHandler(parser->m_handlerArg,

                            parser->m_declEntity->name,

                            0,0,0,

                            parser->m_declEntity->base,

                            parser->m_declEntity->systemId,

                            parser->m_declEntity->publicId,

                            parser->m_declEntity->notation);

          handleDefault = XML_FALSE;

        }

      }

      break;

    case XML_ROLE_GENERAL_ENTITY_NAME:

      {

        if (XmlPredefinedEntityName(enc, s, next)) {

          parser->m_declEntity = NULL;

          break;

        }

        if (dtd->keepProcessing) {

          const XML_Char *name = poolStoreString(&dtd->pool, enc, s, next);

          if (!name)

            return XML_ERROR_NO_MEMORY;

          parser->m_declEntity = (ENTITY *)lookup(parser, &dtd->generalEntities, name,

                                        sizeof(ENTITY));

          if (!parser->m_declEntity)

            return XML_ERROR_NO_MEMORY;

          if (parser->m_declEntity->name != name) {

            poolDiscard(&dtd->pool);

            parser->m_declEntity = NULL;

          }

          else {

            poolFinish(&dtd->pool);

            parser->m_declEntity->publicId = NULL;

            parser->m_declEntity->is_param = XML_FALSE;

            /* if we have a parent parser or are reading an internal parameter

               entity, then the entity declaration is not considered "internal"

            */

            parser->m_declEntity->is_internal = !(parser->m_parentParser || parser->m_openInternalEntities);

            if (parser->m_entityDeclHandler)

              handleDefault = XML_FALSE;

          }

        }

        else {

          poolDiscard(&dtd->pool);

          parser->m_declEntity = NULL;

        }

      }

      break;

    case XML_ROLE_PARAM_ENTITY_NAME:

#ifdef XML_DTD

      if (dtd->keepProcessing) {

        const XML_Char *name = poolStoreString(&dtd->pool, enc, s, next);

        if (!name)

          return XML_ERROR_NO_MEMORY;

        parser->m_declEntity = (ENTITY *)lookup(parser, &dtd->paramEntities,

                                           name, sizeof(ENTITY));

        if (!parser->m_declEntity)

          return XML_ERROR_NO_MEMORY;

        if (parser->m_declEntity->name != name) {

          poolDiscard(&dtd->pool);

          parser->m_declEntity = NULL;

        }

        else {

          poolFinish(&dtd->pool);

          parser->m_declEntity->publicId = NULL;

          parser->m_declEntity->is_param = XML_TRUE;

          /* if we have a parent parser or are reading an internal parameter

             entity, then the entity declaration is not considered "internal"

          */

          parser->m_declEntity->is_internal = !(parser->m_parentParser || parser->m_openInternalEntities);

          if (parser->m_entityDeclHandler)

            handleDefault = XML_FALSE;

        }

      }

      else {

        poolDiscard(&dtd->pool);

        parser->m_declEntity = NULL;

      }

#else /* not XML_DTD */

      parser->m_declEntity = NULL;

#endif /* XML_DTD */

      break;

    case XML_ROLE_NOTATION_NAME:

      parser->m_declNotationPublicId = NULL;

      parser->m_declNotationName = NULL;

      if (parser->m_notationDeclHandler) {

        parser->m_declNotationName = poolStoreString(&parser->m_tempPool, enc, s, next);

        if (!parser->m_declNotationName)

          return XML_ERROR_NO_MEMORY;

        poolFinish(&parser->m_tempPool);

        handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_NOTATION_PUBLIC_ID:

      if (!XmlIsPublicId(enc, s, next, eventPP))

        return XML_ERROR_PUBLICID;

      if (parser->m_declNotationName) {  /* means m_notationDeclHandler != NULL */

        XML_Char *tem = poolStoreString(&parser->m_tempPool,

                                        enc,

                                        s + enc->minBytesPerChar,

                                        next - enc->minBytesPerChar);

        if (!tem)

          return XML_ERROR_NO_MEMORY;

        normalizePublicId(tem);

        parser->m_declNotationPublicId = tem;

        poolFinish(&parser->m_tempPool);

        handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_NOTATION_SYSTEM_ID:

      if (parser->m_declNotationName && parser->m_notationDeclHandler) {

        const XML_Char *systemId

          = poolStoreString(&parser->m_tempPool, enc,

                            s + enc->minBytesPerChar,

                            next - enc->minBytesPerChar);

        if (!systemId)

          return XML_ERROR_NO_MEMORY;

        *eventEndPP = s;

        parser->m_notationDeclHandler(parser->m_handlerArg,

                            parser->m_declNotationName,

                            parser->m_curBase,

                            systemId,

                            parser->m_declNotationPublicId);

        handleDefault = XML_FALSE;

      }

      poolClear(&parser->m_tempPool);

      break;

    case XML_ROLE_NOTATION_NO_SYSTEM_ID:

      if (parser->m_declNotationPublicId && parser->m_notationDeclHandler) {

        *eventEndPP = s;

        parser->m_notationDeclHandler(parser->m_handlerArg,

                            parser->m_declNotationName,

                            parser->m_curBase,

                            0,

                            parser->m_declNotationPublicId);

        handleDefault = XML_FALSE;

      }

      poolClear(&parser->m_tempPool);

      break;

    case XML_ROLE_ERROR:

      switch (tok) {

      case XML_TOK_PARAM_ENTITY_REF:

        /* PE references in internal subset are

           not allowed within declarations. */

        return XML_ERROR_PARAM_ENTITY_REF;

      case XML_TOK_XML_DECL:

        return XML_ERROR_MISPLACED_XML_PI;

      default:

        return XML_ERROR_SYNTAX;

      }

#ifdef XML_DTD

    case XML_ROLE_IGNORE_SECT:

      {

        enum XML_Error result;

        if (parser->m_defaultHandler)

          reportDefault(parser, enc, s, next);

        handleDefault = XML_FALSE;

        result = doIgnoreSection(parser, enc, &next, end, nextPtr, haveMore);

        if (result != XML_ERROR_NONE)

          return result;

        else if (!next) {

          parser->m_processor = ignoreSectionProcessor;

          return result;

        }

      }

      break;

#endif /* XML_DTD */

    case XML_ROLE_GROUP_OPEN:

      if (parser->m_prologState.level >= parser->m_groupSize) {

        if (parser->m_groupSize) {

          char *temp = (char *)REALLOC(parser, parser->m_groupConnector, parser->m_groupSize *= 2);

          if (temp == NULL) {

            parser->m_groupSize /= 2;

            return XML_ERROR_NO_MEMORY;

          }

          parser->m_groupConnector = temp;

          if (dtd->scaffIndex) {

            int *temp = (int *)REALLOC(parser, dtd->scaffIndex,

                          parser->m_groupSize * sizeof(int));

            if (temp == NULL)

              return XML_ERROR_NO_MEMORY;

            dtd->scaffIndex = temp;

          }

        }

        else {

          parser->m_groupConnector = (char *)MALLOC(parser, parser->m_groupSize = 32);

          if (!parser->m_groupConnector) {

            parser->m_groupSize = 0;

            return XML_ERROR_NO_MEMORY;

          }

        }

      }

      parser->m_groupConnector[parser->m_prologState.level] = 0;

      if (dtd->in_eldecl) {

        int myindex = nextScaffoldPart(parser);

        if (myindex < 0)

          return XML_ERROR_NO_MEMORY;

        dtd->scaffIndex[dtd->scaffLevel] = myindex;

        dtd->scaffLevel++;

        dtd->scaffold[myindex].type = XML_CTYPE_SEQ;

        if (parser->m_elementDeclHandler)

          handleDefault = XML_FALSE;

      }

      break;

    case XML_ROLE_GROUP_SEQUENCE:

      if (parser->m_groupConnector[parser->m_prologState.level] == ASCII_PIPE)

        return XML_ERROR_SYNTAX;

      parser->m_groupConnector[parser->m_prologState.level] = ASCII_COMMA;

      if (dtd->in_eldecl && parser->m_elementDeclHandler)

        handleDefault = XML_FALSE;

      break;

    case XML_ROLE_GROUP_CHOICE:

      if (parser->m_groupConnector[parser->m_prologState.level] == ASCII_COMMA)

        return XML_ERROR_SYNTAX;

      if (dtd->in_eldecl

          && !parser->m_groupConnector[parser->m_prologState.level]

          && (dtd->scaffold[dtd->scaffIndex[dtd->scaffLevel - 1]].type

              != XML_CTYPE_MIXED)

          ) {

        dtd->scaffold[dtd->scaffIndex[dtd->scaffLevel - 1]].type

            = XML_CTYPE_CHOICE;

        if (parser->m_elementDeclHandler)

          handleDefault = XML_FALSE;

      }

      parser->m_groupConnector[parser->m_prologState.level] = ASCII_PIPE;

      break;

    case XML_ROLE_PARAM_ENTITY_REF:

#ifdef XML_DTD

    case XML_ROLE_INNER_PARAM_ENTITY_REF:

      dtd->hasParamEntityRefs = XML_TRUE;

      if (!parser->m_paramEntityParsing)

        dtd->keepProcessing = dtd->standalone;

      else {

        const XML_Char *name;

        ENTITY *entity;

        name = poolStoreString(&dtd->pool, enc,

                                s + enc->minBytesPerChar,

                                next - enc->minBytesPerChar);

        if (!name)

          return XML_ERROR_NO_MEMORY;

        entity = (ENTITY *)lookup(parser, &dtd->paramEntities, name, 0);

        poolDiscard(&dtd->pool);

        /* first, determine if a check for an existing declaration is needed;

           if yes, check that the entity exists, and that it is internal,

           otherwise call the skipped entity handler

        */

        if (parser->m_prologState.documentEntity &&

            (dtd->standalone

             ? !parser->m_openInternalEntities

             : !dtd->hasParamEntityRefs)) {

          if (!entity)

            return XML_ERROR_UNDEFINED_ENTITY;

          else if (!entity->is_internal) {

            /* It's hard to exhaustively search the code to be sure,

             * but there doesn't seem to be a way of executing the

             * following line.  There are two cases:

             *

             * If 'standalone' is false, the DTD must have no

             * parameter entities or we wouldn't have passed the outer

             * 'if' statement.  That measn the only entity in the hash

             * table is the external subset name "#" which cannot be

             * given as a parameter entity name in XML syntax, so the

             * lookup must have returned NULL and we don't even reach

             * the test for an internal entity.

             *

             * If 'standalone' is true, it does not seem to be

             * possible to create entities taking this code path that

             * are not internal entities, so fail the test above.

             *

             * Because this analysis is very uncertain, the code is

             * being left in place and merely removed from the

             * coverage test statistics.

             */

            return XML_ERROR_ENTITY_DECLARED_IN_PE; /* LCOV_EXCL_LINE */

          }

        }

        else if (!entity) {

          dtd->keepProcessing = dtd->standalone;

          /* cannot report skipped entities in declarations */

          if ((role == XML_ROLE_PARAM_ENTITY_REF) && parser->m_skippedEntityHandler) {

            parser->m_skippedEntityHandler(parser->m_handlerArg, name, 1);

            handleDefault = XML_FALSE;

          }

          break;

        }

        if (entity->open)

          return XML_ERROR_RECURSIVE_ENTITY_REF;

        if (entity->textPtr) {

          enum XML_Error result;

          XML_Bool betweenDecl =

            (role == XML_ROLE_PARAM_ENTITY_REF ? XML_TRUE : XML_FALSE);

          result = processInternalEntity(parser, entity, betweenDecl);

          if (result != XML_ERROR_NONE)

            return result;

          handleDefault = XML_FALSE;

          break;

        }

        if (parser->m_externalEntityRefHandler) {

          dtd->paramEntityRead = XML_FALSE;

          entity->open = XML_TRUE;

          if (!parser->m_externalEntityRefHandler(parser->m_externalEntityRefHandlerArg,

                                        0,

                                        entity->base,

                                        entity->systemId,

                                        entity->publicId)) {

            entity->open = XML_FALSE;

            return XML_ERROR_EXTERNAL_ENTITY_HANDLING;

          }

          entity->open = XML_FALSE;

          handleDefault = XML_FALSE;

          if (!dtd->paramEntityRead) {

            dtd->keepProcessing = dtd->standalone;

            break;

          }

        }

        else {

          dtd->keepProcessing = dtd->standalone;

          break;

        }

      }

#endif /* XML_DTD */

      if (!dtd->standalone &&

          parser->m_notStandaloneHandler &&

          !parser->m_notStandaloneHandler(parser->m_handlerArg))

        return XML_ERROR_NOT_STANDALONE;

      break;



    /* Element declaration stuff */



    case XML_ROLE_ELEMENT_NAME:

      if (parser->m_elementDeclHandler) {

        parser->m_declElementType = getElementType(parser, enc, s, next);

        if (!parser->m_declElementType)

          return XML_ERROR_NO_MEMORY;

        dtd->scaffLevel = 0;

        dtd->scaffCount = 0;

        dtd->in_eldecl = XML_TRUE;

        handleDefault = XML_FALSE;

      }

      break;



    case XML_ROLE_CONTENT_ANY:

    case XML_ROLE_CONTENT_EMPTY:

      if (dtd->in_eldecl) {

        if (parser->m_elementDeclHandler) {

          XML_Content * content = (XML_Content *) MALLOC(parser, sizeof(XML_Content));

          if (!content)

            return XML_ERROR_NO_MEMORY;

          content->quant = XML_CQUANT_NONE;

          content->name = NULL;

          content->numchildren = 0;

          content->children = NULL;

          content->type = ((role == XML_ROLE_CONTENT_ANY) ?

                           XML_CTYPE_ANY :

                           XML_CTYPE_EMPTY);

          *eventEndPP = s;

          parser->m_elementDeclHandler(parser->m_handlerArg, parser->m_declElementType->name, content);

          handleDefault = XML_FALSE;

        }

        dtd->in_eldecl = XML_FALSE;

      }

      break;



    case XML_ROLE_CONTENT_PCDATA:

      if (dtd->in_eldecl) {

        dtd->scaffold[dtd->scaffIndex[dtd->scaffLevel - 1]].type

            = XML_CTYPE_MIXED;

        if (parser->m_elementDeclHandler)

          handleDefault = XML_FALSE;

      }

      break;



    case XML_ROLE_CONTENT_ELEMENT:

      quant = XML_CQUANT_NONE;

      goto elementContent;

    case XML_ROLE_CONTENT_ELEMENT_OPT:

      quant = XML_CQUANT_OPT;

      goto elementContent;

    case XML_ROLE_CONTENT_ELEMENT_REP:

      quant = XML_CQUANT_REP;

      goto elementContent;

    case XML_ROLE_CONTENT_ELEMENT_PLUS:

      quant = XML_CQUANT_PLUS;

    elementContent:

      if (dtd->in_eldecl) {

        ELEMENT_TYPE *el;

        const XML_Char *name;

        int nameLen;

        const char *nxt = (quant == XML_CQUANT_NONE

                           ? next

                           : next - enc->minBytesPerChar);

        int myindex = nextScaffoldPart(parser);

        if (myindex < 0)

          return XML_ERROR_NO_MEMORY;

        dtd->scaffold[myindex].type = XML_CTYPE_NAME;

        dtd->scaffold[myindex].quant = quant;

        el = getElementType(parser, enc, s, nxt);

        if (!el)

          return XML_ERROR_NO_MEMORY;

        name = el->name;

        dtd->scaffold[myindex].name = name;

        nameLen = 0;

        for (; name[nameLen++]; );

        dtd->contentStringLen +=  nameLen;

        if (parser->m_elementDeclHandler)

          handleDefault = XML_FALSE;

      }

      break;



    case XML_ROLE_GROUP_CLOSE:

      quant = XML_CQUANT_NONE;

      goto closeGroup;

    case XML_ROLE_GROUP_CLOSE_OPT:

      quant = XML_CQUANT_OPT;

      goto closeGroup;

    case XML_ROLE_GROUP_CLOSE_REP:

      quant = XML_CQUANT_REP;

      goto closeGroup;

    case XML_ROLE_GROUP_CLOSE_PLUS:

      quant = XML_CQUANT_PLUS;

    closeGroup:

      if (dtd->in_eldecl) {

        if (parser->m_elementDeclHandler)

          handleDefault = XML_FALSE;

        dtd->scaffLevel--;

        dtd->scaffold[dtd->scaffIndex[dtd->scaffLevel]].quant = quant;

        if (dtd->scaffLevel == 0) {

          if (!handleDefault) {

            XML_Content *model = build_model(parser);

            if (!model)

              return XML_ERROR_NO_MEMORY;

            *eventEndPP = s;

            parser->m_elementDeclHandler(parser->m_handlerArg, parser->m_declElementType->name, model);

          }

          dtd->in_eldecl = XML_FALSE;

          dtd->contentStringLen = 0;

        }

      }

      break;

      /* End element declaration stuff */



    case XML_ROLE_PI:

      if (!reportProcessingInstruction(parser, enc, s, next))

        return XML_ERROR_NO_MEMORY;

      handleDefault = XML_FALSE;

      break;

    case XML_ROLE_COMMENT:

      if (!reportComment(parser, enc, s, next))

        return XML_ERROR_NO_MEMORY;

      handleDefault = XML_FALSE;

      break;

    case XML_ROLE_NONE:

      switch (tok) {

      case XML_TOK_BOM:

        handleDefault = XML_FALSE;

        break;

      }

      break;

    case XML_ROLE_DOCTYPE_NONE:

      if (parser->m_startDoctypeDeclHandler)

        handleDefault = XML_FALSE;

      break;

    case XML_ROLE_ENTITY_NONE:

      if (dtd->keepProcessing && parser->m_entityDeclHandler)

        handleDefault = XML_FALSE;

      break;

    case XML_ROLE_NOTATION_NONE:

      if (parser->m_notationDeclHandler)

        handleDefault = XML_FALSE;

      break;

    case XML_ROLE_ATTLIST_NONE:

      if (dtd->keepProcessing && parser->m_attlistDeclHandler)

        handleDefault = XML_FALSE;

      break;

    case XML_ROLE_ELEMENT_NONE:

      if (parser->m_elementDeclHandler)

        handleDefault = XML_FALSE;

      break;

    } /* end of big switch */



    if (handleDefault && parser->m_defaultHandler)

      reportDefault(parser, enc, s, next);



    switch (parser->m_parsingStatus.parsing) {

    case XML_SUSPENDED:

      *nextPtr = next;

      return XML_ERROR_NONE;

    case XML_FINISHED:

      return XML_ERROR_ABORTED;

    default:

      s = next;

      tok = XmlPrologTok(enc, s, end, &next);

    }

  }

  /* not reached */

}



static enum XML_Error PTRCALL

epilogProcessor(XML_Parser parser,

                const char *s,

                const char *end,

                const char **nextPtr)

{

  parser->m_processor = epilogProcessor;

  parser->m_eventPtr = s;

  for (;;) {

    const char *next = NULL;

    int tok = XmlPrologTok(parser->m_encoding, s, end, &next);

    parser->m_eventEndPtr = next;

    switch (tok) {

    /* report partial linebreak - it might be the last token */

    case -XML_TOK_PROLOG_S:

      if (parser->m_defaultHandler) {

        reportDefault(parser, parser->m_encoding, s, next);

        if (parser->m_parsingStatus.parsing == XML_FINISHED)

          return XML_ERROR_ABORTED;

      }

      *nextPtr = next;

      return XML_ERROR_NONE;

    case XML_TOK_NONE:

      *nextPtr = s;

      return XML_ERROR_NONE;

    case XML_TOK_PROLOG_S:

      if (parser->m_defaultHandler)

        reportDefault(parser, parser->m_encoding, s, next);

      break;

    case XML_TOK_PI:

      if (!reportProcessingInstruction(parser, parser->m_encoding, s, next))

        return XML_ERROR_NO_MEMORY;

      break;

    case XML_TOK_COMMENT:

      if (!reportComment(parser, parser->m_encoding, s, next))

        return XML_ERROR_NO_MEMORY;

      break;

    case XML_TOK_INVALID:

      parser->m_eventPtr = next;

      return XML_ERROR_INVALID_TOKEN;

    case XML_TOK_PARTIAL:

      if (!parser->m_parsingStatus.finalBuffer) {

        *nextPtr = s;

        return XML_ERROR_NONE;

      }

      return XML_ERROR_UNCLOSED_TOKEN;

    case XML_TOK_PARTIAL_CHAR:

      if (!parser->m_parsingStatus.finalBuffer) {

        *nextPtr = s;

        return XML_ERROR_NONE;

      }

      return XML_ERROR_PARTIAL_CHAR;

    default:

      return XML_ERROR_JUNK_AFTER_DOC_ELEMENT;

    }

    parser->m_eventPtr = s = next;

    switch (parser->m_parsingStatus.parsing) {

    case XML_SUSPENDED:

      *nextPtr = next;

      return XML_ERROR_NONE;

    case XML_FINISHED:

      return XML_ERROR_ABORTED;

    default: ;

    }

  }

}



static enum XML_Error

processInternalEntity(XML_Parser parser, ENTITY *entity,

                      XML_Bool betweenDecl)

{

  const char *textStart, *textEnd;

  const char *next;

  enum XML_Error result;

  OPEN_INTERNAL_ENTITY *openEntity;



  if (parser->m_freeInternalEntities) {

    openEntity = parser->m_freeInternalEntities;

    parser->m_freeInternalEntities = openEntity->next;

  }

  else {

    openEntity = (OPEN_INTERNAL_ENTITY *)MALLOC(parser, sizeof(OPEN_INTERNAL_ENTITY));

    if (!openEntity)

      return XML_ERROR_NO_MEMORY;

  }

  entity->open = XML_TRUE;

  entity->processed = 0;

  openEntity->next = parser->m_openInternalEntities;

  parser->m_openInternalEntities = openEntity;

  openEntity->entity = entity;

  openEntity->startTagLevel = parser->m_tagLevel;

  openEntity->betweenDecl = betweenDecl;

  openEntity->internalEventPtr = NULL;

  openEntity->internalEventEndPtr = NULL;

  textStart = (char *)entity->textPtr;

  textEnd = (char *)(entity->textPtr + entity->textLen);

  /* Set a safe default value in case 'next' does not get set */

  next = textStart;



#ifdef XML_DTD

  if (entity->is_param) {

    int tok = XmlPrologTok(parser->m_internalEncoding, textStart, textEnd, &next);

    result = doProlog(parser, parser->m_internalEncoding, textStart, textEnd, tok,

                      next, &next, XML_FALSE);

  }

  else

#endif /* XML_DTD */

    result = doContent(parser, parser->m_tagLevel, parser->m_internalEncoding, textStart,

                       textEnd, &next, XML_FALSE);



  if (result == XML_ERROR_NONE) {

    if (textEnd != next && parser->m_parsingStatus.parsing == XML_SUSPENDED) {

      entity->processed = (int)(next - textStart);

      parser->m_processor = internalEntityProcessor;

    }

    else {

      entity->open = XML_FALSE;

      parser->m_openInternalEntities = openEntity->next;

      /* put openEntity back in list of free instances */

      openEntity->next = parser->m_freeInternalEntities;

      parser->m_freeInternalEntities = openEntity;

    }

  }

  return result;

}



static enum XML_Error PTRCALL

internalEntityProcessor(XML_Parser parser,

                        const char *s,

                        const char *end,

                        const char **nextPtr)

{

  ENTITY *entity;

  const char *textStart, *textEnd;

  const char *next;

  enum XML_Error result;

  OPEN_INTERNAL_ENTITY *openEntity = parser->m_openInternalEntities;

  if (!openEntity)

    return XML_ERROR_UNEXPECTED_STATE;



  entity = openEntity->entity;

  textStart = ((char *)entity->textPtr) + entity->processed;

  textEnd = (char *)(entity->textPtr + entity->textLen);

  /* Set a safe default value in case 'next' does not get set */

  next = textStart;



#ifdef XML_DTD

  if (entity->is_param) {

    int tok = XmlPrologTok(parser->m_internalEncoding, textStart, textEnd, &next);

    result = doProlog(parser, parser->m_internalEncoding, textStart, textEnd, tok,

                      next, &next, XML_FALSE);

  }

  else

#endif /* XML_DTD */

    result = doContent(parser, openEntity->startTagLevel, parser->m_internalEncoding,

                       textStart, textEnd, &next, XML_FALSE);



  if (result != XML_ERROR_NONE)

    return result;

  else if (textEnd != next && parser->m_parsingStatus.parsing == XML_SUSPENDED) {

    entity->processed = (int)(next - (char *)entity->textPtr);

    return result;

  }

  else {

    entity->open = XML_FALSE;

    parser->m_openInternalEntities = openEntity->next;

    /* put openEntity back in list of free instances */

    openEntity->next = parser->m_freeInternalEntities;

    parser->m_freeInternalEntities = openEntity;

  }



#ifdef XML_DTD

  if (entity->is_param) {

    int tok;

    parser->m_processor = prologProcessor;

    tok = XmlPrologTok(parser->m_encoding, s, end, &next);

    return doProlog(parser, parser->m_encoding, s, end, tok, next, nextPtr,

                    (XML_Bool)!parser->m_parsingStatus.finalBuffer);

  }

  else

#endif /* XML_DTD */

  {

    parser->m_processor = contentProcessor;

    /* see externalEntityContentProcessor vs contentProcessor */

    return doContent(parser, parser->m_parentParser ? 1 : 0, parser->m_encoding, s, end,

                     nextPtr, (XML_Bool)!parser->m_parsingStatus.finalBuffer);

  }

}



static enum XML_Error PTRCALL

errorProcessor(XML_Parser parser,

               const char *UNUSED_P(s),

               const char *UNUSED_P(end),

               const char **UNUSED_P(nextPtr))

{

  return parser->m_errorCode;

}



static enum XML_Error

storeAttributeValue(XML_Parser parser, const ENCODING *enc, XML_Bool isCdata,

                    const char *ptr, const char *end,

                    STRING_POOL *pool)

{

  enum XML_Error result = appendAttributeValue(parser, enc, isCdata, ptr,

                                               end, pool);

  if (result)

    return result;

  if (!isCdata && poolLength(pool) && poolLastChar(pool) == 0x20)

    poolChop(pool);

  if (!poolAppendChar(pool, XML_T('\0')))

    return XML_ERROR_NO_MEMORY;

  return XML_ERROR_NONE;

}



static enum XML_Error

appendAttributeValue(XML_Parser parser, const ENCODING *enc, XML_Bool isCdata,

                     const char *ptr, const char *end,

                     STRING_POOL *pool)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  for (;;) {

    const char *next;

    int tok = XmlAttributeValueTok(enc, ptr, end, &next);

    switch (tok) {

    case XML_TOK_NONE:

      return XML_ERROR_NONE;

    case XML_TOK_INVALID:

      if (enc == parser->m_encoding)

        parser->m_eventPtr = next;

      return XML_ERROR_INVALID_TOKEN;

    case XML_TOK_PARTIAL:

      if (enc == parser->m_encoding)

        parser->m_eventPtr = ptr;

      return XML_ERROR_INVALID_TOKEN;

    case XML_TOK_CHAR_REF:

      {

        XML_Char buf[XML_ENCODE_MAX];

        int i;

        int n = XmlCharRefNumber(enc, ptr);

        if (n < 0) {

          if (enc == parser->m_encoding)

            parser->m_eventPtr = ptr;

          return XML_ERROR_BAD_CHAR_REF;

        }

        if (!isCdata

            && n == 0x20 /* space */

            && (poolLength(pool) == 0 || poolLastChar(pool) == 0x20))

          break;

        n = XmlEncode(n, (ICHAR *)buf);

        /* The XmlEncode() functions can never return 0 here.  That

         * error return happens if the code point passed in is either

         * negative or greater than or equal to 0x110000.  The

         * XmlCharRefNumber() functions will all return a number

         * strictly less than 0x110000 or a negative value if an error

         * occurred.  The negative value is intercepted above, so

         * XmlEncode() is never passed a value it might return an

         * error for.

         */

        for (i = 0; i < n; i++) {

          if (!poolAppendChar(pool, buf[i]))

            return XML_ERROR_NO_MEMORY;

        }

      }

      break;

    case XML_TOK_DATA_CHARS:

      if (!poolAppend(pool, enc, ptr, next))

        return XML_ERROR_NO_MEMORY;

      break;

    case XML_TOK_TRAILING_CR:

      next = ptr + enc->minBytesPerChar;

      /* fall through */

    case XML_TOK_ATTRIBUTE_VALUE_S:

    case XML_TOK_DATA_NEWLINE:

      if (!isCdata && (poolLength(pool) == 0 || poolLastChar(pool) == 0x20))

        break;

      if (!poolAppendChar(pool, 0x20))

        return XML_ERROR_NO_MEMORY;

      break;

    case XML_TOK_ENTITY_REF:

      {

        const XML_Char *name;

        ENTITY *entity;

        char checkEntityDecl;

        XML_Char ch = (XML_Char) XmlPredefinedEntityName(enc,

                                              ptr + enc->minBytesPerChar,

                                              next - enc->minBytesPerChar);

        if (ch) {

          if (!poolAppendChar(pool, ch))

                return XML_ERROR_NO_MEMORY;

          break;

        }

        name = poolStoreString(&parser->m_temp2Pool, enc,

                               ptr + enc->minBytesPerChar,

                               next - enc->minBytesPerChar);

        if (!name)

          return XML_ERROR_NO_MEMORY;

        entity = (ENTITY *)lookup(parser, &dtd->generalEntities, name, 0);

        poolDiscard(&parser->m_temp2Pool);

        /* First, determine if a check for an existing declaration is needed;

           if yes, check that the entity exists, and that it is internal.

        */

        if (pool == &dtd->pool)  /* are we called from prolog? */

          checkEntityDecl =

#ifdef XML_DTD

              parser->m_prologState.documentEntity &&

#endif /* XML_DTD */

              (dtd->standalone

               ? !parser->m_openInternalEntities

               : !dtd->hasParamEntityRefs);

        else /* if (pool == &parser->m_tempPool): we are called from content */

          checkEntityDecl = !dtd->hasParamEntityRefs || dtd->standalone;

        if (checkEntityDecl) {

          if (!entity)

            return XML_ERROR_UNDEFINED_ENTITY;

          else if (!entity->is_internal)

            return XML_ERROR_ENTITY_DECLARED_IN_PE;

        }

        else if (!entity) {

          /* Cannot report skipped entity here - see comments on

             parser->m_skippedEntityHandler.

          if (parser->m_skippedEntityHandler)

            parser->m_skippedEntityHandler(parser->m_handlerArg, name, 0);

          */

          /* Cannot call the default handler because this would be

             out of sync with the call to the startElementHandler.

          if ((pool == &parser->m_tempPool) && parser->m_defaultHandler)

            reportDefault(parser, enc, ptr, next);

          */

          break;

        }

        if (entity->open) {

          if (enc == parser->m_encoding) {

            /* It does not appear that this line can be executed.

             *

             * The "if (entity->open)" check catches recursive entity

             * definitions.  In order to be called with an open

             * entity, it must have gone through this code before and

             * been through the recursive call to

             * appendAttributeValue() some lines below.  That call

             * sets the local encoding ("enc") to the parser's

             * internal encoding (internal_utf8 or internal_utf16),

             * which can never be the same as the principle encoding.

             * It doesn't appear there is another code path that gets

             * here with entity->open being TRUE.

             *

             * Since it is not certain that this logic is watertight,

             * we keep the line and merely exclude it from coverage

             * tests.

             */

            parser->m_eventPtr = ptr; /* LCOV_EXCL_LINE */

          }

          return XML_ERROR_RECURSIVE_ENTITY_REF;

        }

        if (entity->notation) {

          if (enc == parser->m_encoding)

            parser->m_eventPtr = ptr;

          return XML_ERROR_BINARY_ENTITY_REF;

        }

        if (!entity->textPtr) {

          if (enc == parser->m_encoding)

            parser->m_eventPtr = ptr;

          return XML_ERROR_ATTRIBUTE_EXTERNAL_ENTITY_REF;

        }

        else {

          enum XML_Error result;

          const XML_Char *textEnd = entity->textPtr + entity->textLen;

          entity->open = XML_TRUE;

          result = appendAttributeValue(parser, parser->m_internalEncoding, isCdata,

                                        (char *)entity->textPtr,

                                        (char *)textEnd, pool);

          entity->open = XML_FALSE;

          if (result)

            return result;

        }

      }

      break;

    default:

      /* The only token returned by XmlAttributeValueTok() that does

       * not have an explicit case here is XML_TOK_PARTIAL_CHAR.

       * Getting that would require an entity name to contain an

       * incomplete XML character (e.g. \xE2\x82); however previous

       * tokenisers will have already recognised and rejected such

       * names before XmlAttributeValueTok() gets a look-in.  This

       * default case should be retained as a safety net, but the code

       * excluded from coverage tests.

       *

       * LCOV_EXCL_START

       */

      if (enc == parser->m_encoding)

        parser->m_eventPtr = ptr;

      return XML_ERROR_UNEXPECTED_STATE;

      /* LCOV_EXCL_STOP */

    }

    ptr = next;

  }

  /* not reached */

}



static enum XML_Error

storeEntityValue(XML_Parser parser,

                 const ENCODING *enc,

                 const char *entityTextPtr,

                 const char *entityTextEnd)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  STRING_POOL *pool = &(dtd->entityValuePool);

  enum XML_Error result = XML_ERROR_NONE;

#ifdef XML_DTD

  int oldInEntityValue = parser->m_prologState.inEntityValue;

  parser->m_prologState.inEntityValue = 1;

#endif /* XML_DTD */

  /* never return Null for the value argument in EntityDeclHandler,

     since this would indicate an external entity; therefore we

     have to make sure that entityValuePool.start is not null */

  if (!pool->blocks) {

    if (!poolGrow(pool))

      return XML_ERROR_NO_MEMORY;

  }



  for (;;) {

    const char *next;

    int tok = XmlEntityValueTok(enc, entityTextPtr, entityTextEnd, &next);

    switch (tok) {

    case XML_TOK_PARAM_ENTITY_REF:

#ifdef XML_DTD

      if (parser->m_isParamEntity || enc != parser->m_encoding) {

        const XML_Char *name;

        ENTITY *entity;

        name = poolStoreString(&parser->m_tempPool, enc,

                               entityTextPtr + enc->minBytesPerChar,

                               next - enc->minBytesPerChar);

        if (!name) {

          result = XML_ERROR_NO_MEMORY;

          goto endEntityValue;

        }

        entity = (ENTITY *)lookup(parser, &dtd->paramEntities, name, 0);

        poolDiscard(&parser->m_tempPool);

        if (!entity) {

          /* not a well-formedness error - see XML 1.0: WFC Entity Declared */

          /* cannot report skipped entity here - see comments on

             parser->m_skippedEntityHandler

          if (parser->m_skippedEntityHandler)

            parser->m_skippedEntityHandler(parser->m_handlerArg, name, 0);

          */

          dtd->keepProcessing = dtd->standalone;

          goto endEntityValue;

        }

        if (entity->open) {

          if (enc == parser->m_encoding)

            parser->m_eventPtr = entityTextPtr;

          result = XML_ERROR_RECURSIVE_ENTITY_REF;

          goto endEntityValue;

        }

        if (entity->systemId) {

          if (parser->m_externalEntityRefHandler) {

            dtd->paramEntityRead = XML_FALSE;

            entity->open = XML_TRUE;

            if (!parser->m_externalEntityRefHandler(parser->m_externalEntityRefHandlerArg,

                                          0,

                                          entity->base,

                                          entity->systemId,

                                          entity->publicId)) {

              entity->open = XML_FALSE;

              result = XML_ERROR_EXTERNAL_ENTITY_HANDLING;

              goto endEntityValue;

            }

            entity->open = XML_FALSE;

            if (!dtd->paramEntityRead)

              dtd->keepProcessing = dtd->standalone;

          }

          else

            dtd->keepProcessing = dtd->standalone;

        }

        else {

          entity->open = XML_TRUE;

          result = storeEntityValue(parser,

                                    parser->m_internalEncoding,

                                    (char *)entity->textPtr,

                                    (char *)(entity->textPtr

                                             + entity->textLen));

          entity->open = XML_FALSE;

          if (result)

            goto endEntityValue;

        }

        break;

      }

#endif /* XML_DTD */

      /* In the internal subset, PE references are not legal

         within markup declarations, e.g entity values in this case. */

      parser->m_eventPtr = entityTextPtr;

      result = XML_ERROR_PARAM_ENTITY_REF;

      goto endEntityValue;

    case XML_TOK_NONE:

      result = XML_ERROR_NONE;

      goto endEntityValue;

    case XML_TOK_ENTITY_REF:

    case XML_TOK_DATA_CHARS:

      if (!poolAppend(pool, enc, entityTextPtr, next)) {

        result = XML_ERROR_NO_MEMORY;

        goto endEntityValue;

      }

      break;

    case XML_TOK_TRAILING_CR:

      next = entityTextPtr + enc->minBytesPerChar;

      /* fall through */

    case XML_TOK_DATA_NEWLINE:

      if (pool->end == pool->ptr && !poolGrow(pool)) {

              result = XML_ERROR_NO_MEMORY;

        goto endEntityValue;

      }

      *(pool->ptr)++ = 0xA;

      break;

    case XML_TOK_CHAR_REF:

      {

        XML_Char buf[XML_ENCODE_MAX];

        int i;

        int n = XmlCharRefNumber(enc, entityTextPtr);

        if (n < 0) {

          if (enc == parser->m_encoding)

            parser->m_eventPtr = entityTextPtr;

          result = XML_ERROR_BAD_CHAR_REF;

          goto endEntityValue;

        }

        n = XmlEncode(n, (ICHAR *)buf);

        /* The XmlEncode() functions can never return 0 here.  That

         * error return happens if the code point passed in is either

         * negative or greater than or equal to 0x110000.  The

         * XmlCharRefNumber() functions will all return a number

         * strictly less than 0x110000 or a negative value if an error

         * occurred.  The negative value is intercepted above, so

         * XmlEncode() is never passed a value it might return an

         * error for.

         */

        for (i = 0; i < n; i++) {

          if (pool->end == pool->ptr && !poolGrow(pool)) {

            result = XML_ERROR_NO_MEMORY;

            goto endEntityValue;

          }

          *(pool->ptr)++ = buf[i];

        }

      }

      break;

    case XML_TOK_PARTIAL:

      if (enc == parser->m_encoding)

        parser->m_eventPtr = entityTextPtr;

      result = XML_ERROR_INVALID_TOKEN;

      goto endEntityValue;

    case XML_TOK_INVALID:

      if (enc == parser->m_encoding)

        parser->m_eventPtr = next;

      result = XML_ERROR_INVALID_TOKEN;

      goto endEntityValue;

    default:

      /* This default case should be unnecessary -- all the tokens

       * that XmlEntityValueTok() can return have their own explicit

       * cases -- but should be retained for safety.  We do however

       * exclude it from the coverage statistics.

       *

       * LCOV_EXCL_START

       */

      if (enc == parser->m_encoding)

        parser->m_eventPtr = entityTextPtr;

      result = XML_ERROR_UNEXPECTED_STATE;

      goto endEntityValue;

      /* LCOV_EXCL_STOP */

    }

    entityTextPtr = next;

  }

endEntityValue:

#ifdef XML_DTD

  parser->m_prologState.inEntityValue = oldInEntityValue;

#endif /* XML_DTD */

  return result;

}



static void FASTCALL

normalizeLines(XML_Char *s)

{

  XML_Char *p;

  for (;; s++) {

    if (*s == XML_T('\0'))

      return;

    if (*s == 0xD)

      break;

  }

  p = s;

  do {

    if (*s == 0xD) {

      *p++ = 0xA;

      if (*++s == 0xA)

        s++;

    }

    else

      *p++ = *s++;

  } while (*s);

  *p = XML_T('\0');

}



static int

reportProcessingInstruction(XML_Parser parser, const ENCODING *enc,

                            const char *start, const char *end)

{

  const XML_Char *target;

  XML_Char *data;

  const char *tem;

  if (!parser->m_processingInstructionHandler) {

    if (parser->m_defaultHandler)

      reportDefault(parser, enc, start, end);

    return 1;

  }

  start += enc->minBytesPerChar * 2;

  tem = start + XmlNameLength(enc, start);

  target = poolStoreString(&parser->m_tempPool, enc, start, tem);

  if (!target)

    return 0;

  poolFinish(&parser->m_tempPool);

  data = poolStoreString(&parser->m_tempPool, enc,

                        XmlSkipS(enc, tem),

                        end - enc->minBytesPerChar*2);

  if (!data)

    return 0;

  normalizeLines(data);

  parser->m_processingInstructionHandler(parser->m_handlerArg, target, data);

  poolClear(&parser->m_tempPool);

  return 1;

}



static int

reportComment(XML_Parser parser, const ENCODING *enc,

              const char *start, const char *end)

{

  XML_Char *data;

  if (!parser->m_commentHandler) {

    if (parser->m_defaultHandler)

      reportDefault(parser, enc, start, end);

    return 1;

  }

  data = poolStoreString(&parser->m_tempPool,

                         enc,

                         start + enc->minBytesPerChar * 4,

                         end - enc->minBytesPerChar * 3);

  if (!data)

    return 0;

  normalizeLines(data);

  parser->m_commentHandler(parser->m_handlerArg, data);

  poolClear(&parser->m_tempPool);

  return 1;

}



static void

reportDefault(XML_Parser parser, const ENCODING *enc,

              const char *s, const char *end)

{

  if (MUST_CONVERT(enc, s)) {

    enum XML_Convert_Result convert_res;

    const char **eventPP;

    const char **eventEndPP;

    if (enc == parser->m_encoding) {

      eventPP = &parser->m_eventPtr;

      eventEndPP = &parser->m_eventEndPtr;

    }

    else {

      /* To get here, two things must be true; the parser must be

       * using a character encoding that is not the same as the

       * encoding passed in, and the encoding passed in must need

       * conversion to the internal format (UTF-8 unless XML_UNICODE

       * is defined).  The only occasions on which the encoding passed

       * in is not the same as the parser's encoding are when it is

       * the internal encoding (e.g. a previously defined parameter

       * entity, already converted to internal format).  This by

       * definition doesn't need conversion, so the whole branch never

       * gets executed.

       *

       * For safety's sake we don't delete these lines and merely

       * exclude them from coverage statistics.

       *

       * LCOV_EXCL_START

       */

      eventPP = &(parser->m_openInternalEntities->internalEventPtr);

      eventEndPP = &(parser->m_openInternalEntities->internalEventEndPtr);

      /* LCOV_EXCL_STOP */

    }

    do {

      ICHAR *dataPtr = (ICHAR *)parser->m_dataBuf;

      convert_res = XmlConvert(enc, &s, end, &dataPtr, (ICHAR *)parser->m_dataBufEnd);

      *eventEndPP = s;

      parser->m_defaultHandler(parser->m_handlerArg, parser->m_dataBuf, (int)(dataPtr - (ICHAR *)parser->m_dataBuf));

      *eventPP = s;

    } while ((convert_res != XML_CONVERT_COMPLETED) && (convert_res != XML_CONVERT_INPUT_INCOMPLETE));

  }

  else

    parser->m_defaultHandler(parser->m_handlerArg, (XML_Char *)s, (int)((XML_Char *)end - (XML_Char *)s));

}





static int

defineAttribute(ELEMENT_TYPE *type, ATTRIBUTE_ID *attId, XML_Bool isCdata,

                XML_Bool isId, const XML_Char *value, XML_Parser parser)

{

  DEFAULT_ATTRIBUTE *att;

  if (value || isId) {

    /* The handling of default attributes gets messed up if we have

       a default which duplicates a non-default. */

    int i;

    for (i = 0; i < type->nDefaultAtts; i++)

      if (attId == type->defaultAtts[i].id)

        return 1;

    if (isId && !type->idAtt && !attId->xmlns)

      type->idAtt = attId;

  }

  if (type->nDefaultAtts == type->allocDefaultAtts) {

    if (type->allocDefaultAtts == 0) {

      type->allocDefaultAtts = 8;

      type->defaultAtts = (DEFAULT_ATTRIBUTE *)MALLOC(parser, type->allocDefaultAtts

                            * sizeof(DEFAULT_ATTRIBUTE));

      if (!type->defaultAtts) {

        type->allocDefaultAtts = 0;

        return 0;

      }

    }

    else {

      DEFAULT_ATTRIBUTE *temp;

      int count = type->allocDefaultAtts * 2;

      temp = (DEFAULT_ATTRIBUTE *)

        REALLOC(parser, type->defaultAtts, (count * sizeof(DEFAULT_ATTRIBUTE)));

      if (temp == NULL)

        return 0;

      type->allocDefaultAtts = count;

      type->defaultAtts = temp;

    }

  }

  att = type->defaultAtts + type->nDefaultAtts;

  att->id = attId;

  att->value = value;

  att->isCdata = isCdata;

  if (!isCdata)

    attId->maybeTokenized = XML_TRUE;

  type->nDefaultAtts += 1;

  return 1;

}



static int

setElementTypePrefix(XML_Parser parser, ELEMENT_TYPE *elementType)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  const XML_Char *name;

  for (name = elementType->name; *name; name++) {

    if (*name == XML_T(ASCII_COLON)) {

      PREFIX *prefix;

      const XML_Char *s;

      for (s = elementType->name; s != name; s++) {

        if (!poolAppendChar(&dtd->pool, *s))

          return 0;

      }

      if (!poolAppendChar(&dtd->pool, XML_T('\0')))

        return 0;

      prefix = (PREFIX *)lookup(parser, &dtd->prefixes, poolStart(&dtd->pool),

                                sizeof(PREFIX));

      if (!prefix)

        return 0;

      if (prefix->name == poolStart(&dtd->pool))

        poolFinish(&dtd->pool);

      else

        poolDiscard(&dtd->pool);

      elementType->prefix = prefix;

      break;

    }

  }

  return 1;

}



static ATTRIBUTE_ID *

getAttributeId(XML_Parser parser, const ENCODING *enc,

               const char *start, const char *end)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  ATTRIBUTE_ID *id;

  const XML_Char *name;

  if (!poolAppendChar(&dtd->pool, XML_T('\0')))

    return NULL;

  name = poolStoreString(&dtd->pool, enc, start, end);

  if (!name)

    return NULL;

  /* skip quotation mark - its storage will be re-used (like in name[-1]) */

  ++name;

  id = (ATTRIBUTE_ID *)lookup(parser, &dtd->attributeIds, name, sizeof(ATTRIBUTE_ID));

  if (!id)

    return NULL;

  if (id->name != name)

    poolDiscard(&dtd->pool);

  else {

    poolFinish(&dtd->pool);

    if (!parser->m_ns)

      ;

    else if (name[0] == XML_T(ASCII_x)

        && name[1] == XML_T(ASCII_m)

        && name[2] == XML_T(ASCII_l)

        && name[3] == XML_T(ASCII_n)

        && name[4] == XML_T(ASCII_s)

        && (name[5] == XML_T('\0') || name[5] == XML_T(ASCII_COLON))) {

      if (name[5] == XML_T('\0'))

        id->prefix = &dtd->defaultPrefix;

      else

        id->prefix = (PREFIX *)lookup(parser, &dtd->prefixes, name + 6, sizeof(PREFIX));

      id->xmlns = XML_TRUE;

    }

    else {

      int i;

      for (i = 0; name[i]; i++) {

        /* attributes without prefix are *not* in the default namespace */

        if (name[i] == XML_T(ASCII_COLON)) {

          int j;

          for (j = 0; j < i; j++) {

            if (!poolAppendChar(&dtd->pool, name[j]))

              return NULL;

          }

          if (!poolAppendChar(&dtd->pool, XML_T('\0')))

            return NULL;

          id->prefix = (PREFIX *)lookup(parser, &dtd->prefixes, poolStart(&dtd->pool),

                                        sizeof(PREFIX));

          if (!id->prefix)

            return NULL;

          if (id->prefix->name == poolStart(&dtd->pool))

            poolFinish(&dtd->pool);

          else

            poolDiscard(&dtd->pool);

          break;

        }

      }

    }

  }

  return id;

}



#define CONTEXT_SEP XML_T(ASCII_FF)



static const XML_Char *

getContext(XML_Parser parser)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  HASH_TABLE_ITER iter;

  XML_Bool needSep = XML_FALSE;



  if (dtd->defaultPrefix.binding) {

    int i;

    int len;

    if (!poolAppendChar(&parser->m_tempPool, XML_T(ASCII_EQUALS)))

      return NULL;

    len = dtd->defaultPrefix.binding->uriLen;

    if (parser->m_namespaceSeparator)

      len--;

    for (i = 0; i < len; i++) {

      if (!poolAppendChar(&parser->m_tempPool, dtd->defaultPrefix.binding->uri[i])) {

        /* Because of memory caching, I don't believe this line can be

         * executed.

         *

         * This is part of a loop copying the default prefix binding

         * URI into the parser's temporary string pool.  Previously,

         * that URI was copied into the same string pool, with a

         * terminating NUL character, as part of setContext().  When

         * the pool was cleared, that leaves a block definitely big

         * enough to hold the URI on the free block list of the pool.

         * The URI copy in getContext() therefore cannot run out of

         * memory.

         *

         * If the pool is used between the setContext() and

         * getContext() calls, the worst it can do is leave a bigger

         * block on the front of the free list.  Given that this is

         * all somewhat inobvious and program logic can be changed, we

         * don't delete the line but we do exclude it from the test

         * coverage statistics.

         */

        return NULL; /* LCOV_EXCL_LINE */

      }

    }

    needSep = XML_TRUE;

  }



  hashTableIterInit(&iter, &(dtd->prefixes));

  for (;;) {

    int i;

    int len;

    const XML_Char *s;

    PREFIX *prefix = (PREFIX *)hashTableIterNext(&iter);

    if (!prefix)

      break;

    if (!prefix->binding) {

      /* This test appears to be (justifiable) paranoia.  There does

       * not seem to be a way of injecting a prefix without a binding

       * that doesn't get errored long before this function is called.

       * The test should remain for safety's sake, so we instead

       * exclude the following line from the coverage statistics.

       */

      continue; /* LCOV_EXCL_LINE */

    }

    if (needSep && !poolAppendChar(&parser->m_tempPool, CONTEXT_SEP))

      return NULL;

    for (s = prefix->name; *s; s++)

      if (!poolAppendChar(&parser->m_tempPool, *s))

        return NULL;

    if (!poolAppendChar(&parser->m_tempPool, XML_T(ASCII_EQUALS)))

      return NULL;

    len = prefix->binding->uriLen;

    if (parser->m_namespaceSeparator)

      len--;

    for (i = 0; i < len; i++)

      if (!poolAppendChar(&parser->m_tempPool, prefix->binding->uri[i]))

        return NULL;

    needSep = XML_TRUE;

  }





  hashTableIterInit(&iter, &(dtd->generalEntities));

  for (;;) {

    const XML_Char *s;

    ENTITY *e = (ENTITY *)hashTableIterNext(&iter);

    if (!e)

      break;

    if (!e->open)

      continue;

    if (needSep && !poolAppendChar(&parser->m_tempPool, CONTEXT_SEP))

      return NULL;

    for (s = e->name; *s; s++)

      if (!poolAppendChar(&parser->m_tempPool, *s))

        return 0;

    needSep = XML_TRUE;

  }



  if (!poolAppendChar(&parser->m_tempPool, XML_T('\0')))

    return NULL;

  return parser->m_tempPool.start;

}



static XML_Bool

setContext(XML_Parser parser, const XML_Char *context)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  const XML_Char *s = context;



  while (*context != XML_T('\0')) {

    if (*s == CONTEXT_SEP || *s == XML_T('\0')) {

      ENTITY *e;

      if (!poolAppendChar(&parser->m_tempPool, XML_T('\0')))

        return XML_FALSE;

      e = (ENTITY *)lookup(parser, &dtd->generalEntities, poolStart(&parser->m_tempPool), 0);

      if (e)

        e->open = XML_TRUE;

      if (*s != XML_T('\0'))

        s++;

      context = s;

      poolDiscard(&parser->m_tempPool);

    }

    else if (*s == XML_T(ASCII_EQUALS)) {

      PREFIX *prefix;

      if (poolLength(&parser->m_tempPool) == 0)

        prefix = &dtd->defaultPrefix;

      else {

        if (!poolAppendChar(&parser->m_tempPool, XML_T('\0')))

          return XML_FALSE;

        prefix = (PREFIX *)lookup(parser, &dtd->prefixes, poolStart(&parser->m_tempPool),

                                  sizeof(PREFIX));

        if (!prefix)

          return XML_FALSE;

        if (prefix->name == poolStart(&parser->m_tempPool)) {

          prefix->name = poolCopyString(&dtd->pool, prefix->name);

          if (!prefix->name)

            return XML_FALSE;

        }

        poolDiscard(&parser->m_tempPool);

      }

      for (context = s + 1;

           *context != CONTEXT_SEP && *context != XML_T('\0');

           context++)

        if (!poolAppendChar(&parser->m_tempPool, *context))

          return XML_FALSE;

      if (!poolAppendChar(&parser->m_tempPool, XML_T('\0')))

        return XML_FALSE;

      if (addBinding(parser, prefix, NULL, poolStart(&parser->m_tempPool),

                     &parser->m_inheritedBindings) != XML_ERROR_NONE)

        return XML_FALSE;

      poolDiscard(&parser->m_tempPool);

      if (*context != XML_T('\0'))

        ++context;

      s = context;

    }

    else {

      if (!poolAppendChar(&parser->m_tempPool, *s))

        return XML_FALSE;

      s++;

    }

  }

  return XML_TRUE;

}



static void FASTCALL

normalizePublicId(XML_Char *publicId)

{

  XML_Char *p = publicId;

  XML_Char *s;

  for (s = publicId; *s; s++) {

    switch (*s) {

    case 0x20:

    case 0xD:

    case 0xA:

      if (p != publicId && p[-1] != 0x20)

        *p++ = 0x20;

      break;

    default:

      *p++ = *s;

    }

  }

  if (p != publicId && p[-1] == 0x20)

    --p;

  *p = XML_T('\0');

}



static DTD *

dtdCreate(const XML_Memory_Handling_Suite *ms)

{

  DTD *p = (DTD *)ms->malloc_fcn(sizeof(DTD));

  if (p == NULL)

    return p;

  poolInit(&(p->pool), ms);

  poolInit(&(p->entityValuePool), ms);

  hashTableInit(&(p->generalEntities), ms);

  hashTableInit(&(p->elementTypes), ms);

  hashTableInit(&(p->attributeIds), ms);

  hashTableInit(&(p->prefixes), ms);

#ifdef XML_DTD

  p->paramEntityRead = XML_FALSE;

  hashTableInit(&(p->paramEntities), ms);

#endif /* XML_DTD */

  p->defaultPrefix.name = NULL;

  p->defaultPrefix.binding = NULL;



  p->in_eldecl = XML_FALSE;

  p->scaffIndex = NULL;

  p->scaffold = NULL;

  p->scaffLevel = 0;

  p->scaffSize = 0;

  p->scaffCount = 0;

  p->contentStringLen = 0;



  p->keepProcessing = XML_TRUE;

  p->hasParamEntityRefs = XML_FALSE;

  p->standalone = XML_FALSE;

  return p;

}



static void

dtdReset(DTD *p, const XML_Memory_Handling_Suite *ms)

{

  HASH_TABLE_ITER iter;

  hashTableIterInit(&iter, &(p->elementTypes));

  for (;;) {

    ELEMENT_TYPE *e = (ELEMENT_TYPE *)hashTableIterNext(&iter);

    if (!e)

      break;

    if (e->allocDefaultAtts != 0)

      ms->free_fcn(e->defaultAtts);

  }

  hashTableClear(&(p->generalEntities));

#ifdef XML_DTD

  p->paramEntityRead = XML_FALSE;

  hashTableClear(&(p->paramEntities));

#endif /* XML_DTD */

  hashTableClear(&(p->elementTypes));

  hashTableClear(&(p->attributeIds));

  hashTableClear(&(p->prefixes));

  poolClear(&(p->pool));

  poolClear(&(p->entityValuePool));

  p->defaultPrefix.name = NULL;

  p->defaultPrefix.binding = NULL;



  p->in_eldecl = XML_FALSE;



  ms->free_fcn(p->scaffIndex);

  p->scaffIndex = NULL;

  ms->free_fcn(p->scaffold);

  p->scaffold = NULL;



  p->scaffLevel = 0;

  p->scaffSize = 0;

  p->scaffCount = 0;

  p->contentStringLen = 0;



  p->keepProcessing = XML_TRUE;

  p->hasParamEntityRefs = XML_FALSE;

  p->standalone = XML_FALSE;

}



static void

dtdDestroy(DTD *p, XML_Bool isDocEntity, const XML_Memory_Handling_Suite *ms)

{

  HASH_TABLE_ITER iter;

  hashTableIterInit(&iter, &(p->elementTypes));

  for (;;) {

    ELEMENT_TYPE *e = (ELEMENT_TYPE *)hashTableIterNext(&iter);

    if (!e)

      break;

    if (e->allocDefaultAtts != 0)

      ms->free_fcn(e->defaultAtts);

  }

  hashTableDestroy(&(p->generalEntities));

#ifdef XML_DTD

  hashTableDestroy(&(p->paramEntities));

#endif /* XML_DTD */

  hashTableDestroy(&(p->elementTypes));

  hashTableDestroy(&(p->attributeIds));

  hashTableDestroy(&(p->prefixes));

  poolDestroy(&(p->pool));

  poolDestroy(&(p->entityValuePool));

  if (isDocEntity) {

    ms->free_fcn(p->scaffIndex);

    ms->free_fcn(p->scaffold);

  }

  ms->free_fcn(p);

}



/* Do a deep copy of the DTD. Return 0 for out of memory, non-zero otherwise.

   The new DTD has already been initialized.

*/

static int

dtdCopy(XML_Parser oldParser, DTD *newDtd, const DTD *oldDtd, const XML_Memory_Handling_Suite *ms)

{

  HASH_TABLE_ITER iter;



  /* Copy the prefix table. */



  hashTableIterInit(&iter, &(oldDtd->prefixes));

  for (;;) {

    const XML_Char *name;

    const PREFIX *oldP = (PREFIX *)hashTableIterNext(&iter);

    if (!oldP)

      break;

    name = poolCopyString(&(newDtd->pool), oldP->name);

    if (!name)

      return 0;

    if (!lookup(oldParser, &(newDtd->prefixes), name, sizeof(PREFIX)))

      return 0;

  }



  hashTableIterInit(&iter, &(oldDtd->attributeIds));



  /* Copy the attribute id table. */



  for (;;) {

    ATTRIBUTE_ID *newA;

    const XML_Char *name;

    const ATTRIBUTE_ID *oldA = (ATTRIBUTE_ID *)hashTableIterNext(&iter);



    if (!oldA)

      break;

    /* Remember to allocate the scratch byte before the name. */

    if (!poolAppendChar(&(newDtd->pool), XML_T('\0')))

      return 0;

    name = poolCopyString(&(newDtd->pool), oldA->name);

    if (!name)

      return 0;

    ++name;

    newA = (ATTRIBUTE_ID *)lookup(oldParser, &(newDtd->attributeIds), name,

                                  sizeof(ATTRIBUTE_ID));

    if (!newA)

      return 0;

    newA->maybeTokenized = oldA->maybeTokenized;

    if (oldA->prefix) {

      newA->xmlns = oldA->xmlns;

      if (oldA->prefix == &oldDtd->defaultPrefix)

        newA->prefix = &newDtd->defaultPrefix;

      else

        newA->prefix = (PREFIX *)lookup(oldParser, &(newDtd->prefixes),

                                        oldA->prefix->name, 0);

    }

  }



  /* Copy the element type table. */



  hashTableIterInit(&iter, &(oldDtd->elementTypes));



  for (;;) {

    int i;

    ELEMENT_TYPE *newE;

    const XML_Char *name;

    const ELEMENT_TYPE *oldE = (ELEMENT_TYPE *)hashTableIterNext(&iter);

    if (!oldE)

      break;

    name = poolCopyString(&(newDtd->pool), oldE->name);

    if (!name)

      return 0;

    newE = (ELEMENT_TYPE *)lookup(oldParser, &(newDtd->elementTypes), name,

                                  sizeof(ELEMENT_TYPE));

    if (!newE)

      return 0;

    if (oldE->nDefaultAtts) {

      newE->defaultAtts = (DEFAULT_ATTRIBUTE *)

          ms->malloc_fcn(oldE->nDefaultAtts * sizeof(DEFAULT_ATTRIBUTE));

      if (!newE->defaultAtts) {

        return 0;

      }

    }

    if (oldE->idAtt)

      newE->idAtt = (ATTRIBUTE_ID *)

          lookup(oldParser, &(newDtd->attributeIds), oldE->idAtt->name, 0);

    newE->allocDefaultAtts = newE->nDefaultAtts = oldE->nDefaultAtts;

    if (oldE->prefix)

      newE->prefix = (PREFIX *)lookup(oldParser, &(newDtd->prefixes),

                                      oldE->prefix->name, 0);

    for (i = 0; i < newE->nDefaultAtts; i++) {

      newE->defaultAtts[i].id = (ATTRIBUTE_ID *)

          lookup(oldParser, &(newDtd->attributeIds), oldE->defaultAtts[i].id->name, 0);

      newE->defaultAtts[i].isCdata = oldE->defaultAtts[i].isCdata;

      if (oldE->defaultAtts[i].value) {

        newE->defaultAtts[i].value

            = poolCopyString(&(newDtd->pool), oldE->defaultAtts[i].value);

        if (!newE->defaultAtts[i].value)

          return 0;

      }

      else

        newE->defaultAtts[i].value = NULL;

    }

  }



  /* Copy the entity tables. */

  if (!copyEntityTable(oldParser,

                       &(newDtd->generalEntities),

                       &(newDtd->pool),

                       &(oldDtd->generalEntities)))

      return 0;



#ifdef XML_DTD

  if (!copyEntityTable(oldParser,

                       &(newDtd->paramEntities),

                       &(newDtd->pool),

                       &(oldDtd->paramEntities)))

      return 0;

  newDtd->paramEntityRead = oldDtd->paramEntityRead;

#endif /* XML_DTD */



  newDtd->keepProcessing = oldDtd->keepProcessing;

  newDtd->hasParamEntityRefs = oldDtd->hasParamEntityRefs;

  newDtd->standalone = oldDtd->standalone;



  /* Don't want deep copying for scaffolding */

  newDtd->in_eldecl = oldDtd->in_eldecl;

  newDtd->scaffold = oldDtd->scaffold;

  newDtd->contentStringLen = oldDtd->contentStringLen;

  newDtd->scaffSize = oldDtd->scaffSize;

  newDtd->scaffLevel = oldDtd->scaffLevel;

  newDtd->scaffIndex = oldDtd->scaffIndex;



  return 1;

}  /* End dtdCopy */



static int

copyEntityTable(XML_Parser oldParser,

                HASH_TABLE *newTable,

                STRING_POOL *newPool,

                const HASH_TABLE *oldTable)

{

  HASH_TABLE_ITER iter;

  const XML_Char *cachedOldBase = NULL;

  const XML_Char *cachedNewBase = NULL;



  hashTableIterInit(&iter, oldTable);



  for (;;) {

    ENTITY *newE;

    const XML_Char *name;

    const ENTITY *oldE = (ENTITY *)hashTableIterNext(&iter);

    if (!oldE)

      break;

    name = poolCopyString(newPool, oldE->name);

    if (!name)

      return 0;

    newE = (ENTITY *)lookup(oldParser, newTable, name, sizeof(ENTITY));

    if (!newE)

      return 0;

    if (oldE->systemId) {

      const XML_Char *tem = poolCopyString(newPool, oldE->systemId);

      if (!tem)

        return 0;

      newE->systemId = tem;

      if (oldE->base) {

        if (oldE->base == cachedOldBase)

          newE->base = cachedNewBase;

        else {

          cachedOldBase = oldE->base;

          tem = poolCopyString(newPool, cachedOldBase);

          if (!tem)

            return 0;

          cachedNewBase = newE->base = tem;

        }

      }

      if (oldE->publicId) {

        tem = poolCopyString(newPool, oldE->publicId);

        if (!tem)

          return 0;

        newE->publicId = tem;

      }

    }

    else {

      const XML_Char *tem = poolCopyStringN(newPool, oldE->textPtr,

                                            oldE->textLen);

      if (!tem)

        return 0;

      newE->textPtr = tem;

      newE->textLen = oldE->textLen;

    }

    if (oldE->notation) {

      const XML_Char *tem = poolCopyString(newPool, oldE->notation);

      if (!tem)

        return 0;

      newE->notation = tem;

    }

    newE->is_param = oldE->is_param;

    newE->is_internal = oldE->is_internal;

  }

  return 1;

}



#define INIT_POWER 6



static XML_Bool FASTCALL

keyeq(KEY s1, KEY s2)

{

  for (; *s1 == *s2; s1++, s2++)

    if (*s1 == 0)

      return XML_TRUE;

  return XML_FALSE;

}



static size_t

keylen(KEY s)

{

  size_t len = 0;

  for (; *s; s++, len++);

  return len;

}



static void

copy_salt_to_sipkey(XML_Parser parser, struct sipkey * key)

{

  key->k[0] = 0;

  key->k[1] = get_hash_secret_salt(parser);

}



static unsigned long FASTCALL

hash(XML_Parser parser, KEY s)

{

  struct siphash state;

  struct sipkey key;

  (void)sip24_valid;

  copy_salt_to_sipkey(parser, &key);

  sip24_init(&state, &key);

  sip24_update(&state, s, keylen(s) * sizeof(XML_Char));

  return (unsigned long)sip24_final(&state);

}



static NAMED *

lookup(XML_Parser parser, HASH_TABLE *table, KEY name, size_t createSize)

{

  size_t i;

  if (table->size == 0) {

    size_t tsize;

    if (!createSize)

      return NULL;

    table->power = INIT_POWER;

    /* table->size is a power of 2 */

    table->size = (size_t)1 << INIT_POWER;

    tsize = table->size * sizeof(NAMED *);

    table->v = (NAMED **)table->mem->malloc_fcn(tsize);

    if (!table->v) {

      table->size = 0;

      return NULL;

    }

    memset(table->v, 0, tsize);

    i = hash(parser, name) & ((unsigned long)table->size - 1);

  }

  else {

    unsigned long h = hash(parser, name);

    unsigned long mask = (unsigned long)table->size - 1;

    unsigned char step = 0;

    i = h & mask;

    while (table->v[i]) {

      if (keyeq(name, table->v[i]->name))

        return table->v[i];

      if (!step)

        step = PROBE_STEP(h, mask, table->power);

      i < step ? (i += table->size - step) : (i -= step);

    }

    if (!createSize)

      return NULL;



    /* check for overflow (table is half full) */

    if (table->used >> (table->power - 1)) {

      unsigned char newPower = table->power + 1;

      size_t newSize = (size_t)1 << newPower;

      unsigned long newMask = (unsigned long)newSize - 1;

      size_t tsize = newSize * sizeof(NAMED *);

      NAMED **newV = (NAMED **)table->mem->malloc_fcn(tsize);

      if (!newV)

        return NULL;

      memset(newV, 0, tsize);

      for (i = 0; i < table->size; i++)

        if (table->v[i]) {

          unsigned long newHash = hash(parser, table->v[i]->name);

          size_t j = newHash & newMask;

          step = 0;

          while (newV[j]) {

            if (!step)

              step = PROBE_STEP(newHash, newMask, newPower);

            j < step ? (j += newSize - step) : (j -= step);

          }

          newV[j] = table->v[i];

        }

      table->mem->free_fcn(table->v);

      table->v = newV;

      table->power = newPower;

      table->size = newSize;

      i = h & newMask;

      step = 0;

      while (table->v[i]) {

        if (!step)

          step = PROBE_STEP(h, newMask, newPower);

        i < step ? (i += newSize - step) : (i -= step);

      }

    }

  }

  table->v[i] = (NAMED *)table->mem->malloc_fcn(createSize);

  if (!table->v[i])

    return NULL;

  memset(table->v[i], 0, createSize);

  table->v[i]->name = name;

  (table->used)++;

  return table->v[i];

}



static void FASTCALL

hashTableClear(HASH_TABLE *table)

{

  size_t i;

  for (i = 0; i < table->size; i++) {

    table->mem->free_fcn(table->v[i]);

    table->v[i] = NULL;

  }

  table->used = 0;

}



static void FASTCALL

hashTableDestroy(HASH_TABLE *table)

{

  size_t i;

  for (i = 0; i < table->size; i++)

    table->mem->free_fcn(table->v[i]);

  table->mem->free_fcn(table->v);

}



static void FASTCALL

hashTableInit(HASH_TABLE *p, const XML_Memory_Handling_Suite *ms)

{

  p->power = 0;

  p->size = 0;

  p->used = 0;

  p->v = NULL;

  p->mem = ms;

}



static void FASTCALL

hashTableIterInit(HASH_TABLE_ITER *iter, const HASH_TABLE *table)

{

  iter->p = table->v;

  iter->end = iter->p + table->size;

}



static NAMED * FASTCALL

hashTableIterNext(HASH_TABLE_ITER *iter)

{

  while (iter->p != iter->end) {

    NAMED *tem = *(iter->p)++;

    if (tem)

      return tem;

  }

  return NULL;

}



static void FASTCALL

poolInit(STRING_POOL *pool, const XML_Memory_Handling_Suite *ms)

{

  pool->blocks = NULL;

  pool->freeBlocks = NULL;

  pool->start = NULL;

  pool->ptr = NULL;

  pool->end = NULL;

  pool->mem = ms;

}



static void FASTCALL

poolClear(STRING_POOL *pool)

{

  if (!pool->freeBlocks)

    pool->freeBlocks = pool->blocks;

  else {

    BLOCK *p = pool->blocks;

    while (p) {

      BLOCK *tem = p->next;

      p->next = pool->freeBlocks;

      pool->freeBlocks = p;

      p = tem;

    }

  }

  pool->blocks = NULL;

  pool->start = NULL;

  pool->ptr = NULL;

  pool->end = NULL;

}



static void FASTCALL

poolDestroy(STRING_POOL *pool)

{

  BLOCK *p = pool->blocks;

  while (p) {

    BLOCK *tem = p->next;

    pool->mem->free_fcn(p);

    p = tem;

  }

  p = pool->freeBlocks;

  while (p) {

    BLOCK *tem = p->next;

    pool->mem->free_fcn(p);

    p = tem;

  }

}



static XML_Char *

poolAppend(STRING_POOL *pool, const ENCODING *enc,

           const char *ptr, const char *end)

{

  if (!pool->ptr && !poolGrow(pool))

    return NULL;

  for (;;) {

    const enum XML_Convert_Result convert_res = XmlConvert(enc, &ptr, end, (ICHAR **)&(pool->ptr), (ICHAR *)pool->end);

    if ((convert_res == XML_CONVERT_COMPLETED) || (convert_res == XML_CONVERT_INPUT_INCOMPLETE))

      break;

    if (!poolGrow(pool))

      return NULL;

  }

  return pool->start;

}



static const XML_Char * FASTCALL

poolCopyString(STRING_POOL *pool, const XML_Char *s)

{

  do {

    if (!poolAppendChar(pool, *s))

      return NULL;

  } while (*s++);

  s = pool->start;

  poolFinish(pool);

  return s;

}



static const XML_Char *

poolCopyStringN(STRING_POOL *pool, const XML_Char *s, int n)

{

  if (!pool->ptr && !poolGrow(pool)) {

    /* The following line is unreachable given the current usage of

     * poolCopyStringN().  Currently it is called from exactly one

     * place to copy the text of a simple general entity.  By that

     * point, the name of the entity is already stored in the pool, so

     * pool->ptr cannot be NULL.

     *

     * If poolCopyStringN() is used elsewhere as it well might be,

     * this line may well become executable again.  Regardless, this

     * sort of check shouldn't be removed lightly, so we just exclude

     * it from the coverage statistics.

     */

    return NULL; /* LCOV_EXCL_LINE */

  }

  for (; n > 0; --n, s++) {

    if (!poolAppendChar(pool, *s))

      return NULL;

  }

  s = pool->start;

  poolFinish(pool);

  return s;

}



static const XML_Char * FASTCALL

poolAppendString(STRING_POOL *pool, const XML_Char *s)

{

  while (*s) {

    if (!poolAppendChar(pool, *s))

      return NULL;

    s++;

  }

  return pool->start;

}



static XML_Char *

poolStoreString(STRING_POOL *pool, const ENCODING *enc,

                const char *ptr, const char *end)

{

  if (!poolAppend(pool, enc, ptr, end))

    return NULL;

  if (pool->ptr == pool->end && !poolGrow(pool))

    return NULL;

  *(pool->ptr)++ = 0;

  return pool->start;

}



static size_t

poolBytesToAllocateFor(int blockSize)

{

  /* Unprotected math would be:

  ** return offsetof(BLOCK, s) + blockSize * sizeof(XML_Char);

  **

  ** Detect overflow, avoiding _signed_ overflow undefined behavior

  ** For a + b * c we check b * c in isolation first, so that addition of a

  ** on top has no chance of making us accept a small non-negative number

  */

  const size_t stretch = sizeof(XML_Char);  /* can be 4 bytes */



  if (blockSize <= 0)

    return 0;



  if (blockSize > (int)(INT_MAX / stretch))

    return 0;



  {

    const int stretchedBlockSize = blockSize * (int)stretch;

    const int bytesToAllocate = (int)(

        offsetof(BLOCK, s) + (unsigned)stretchedBlockSize);

    if (bytesToAllocate < 0)

      return 0;



    return (size_t)bytesToAllocate;

  }

}



static XML_Bool FASTCALL

poolGrow(STRING_POOL *pool)

{

  if (pool->freeBlocks) {

    if (pool->start == 0) {

      pool->blocks = pool->freeBlocks;

      pool->freeBlocks = pool->freeBlocks->next;

      pool->blocks->next = NULL;

      pool->start = pool->blocks->s;

      pool->end = pool->start + pool->blocks->size;

      pool->ptr = pool->start;

      return XML_TRUE;

    }

    if (pool->end - pool->start < pool->freeBlocks->size) {

      BLOCK *tem = pool->freeBlocks->next;

      pool->freeBlocks->next = pool->blocks;

      pool->blocks = pool->freeBlocks;

      pool->freeBlocks = tem;

      memcpy(pool->blocks->s, pool->start,

             (pool->end - pool->start) * sizeof(XML_Char));

      pool->ptr = pool->blocks->s + (pool->ptr - pool->start);

      pool->start = pool->blocks->s;

      pool->end = pool->start + pool->blocks->size;

      return XML_TRUE;

    }

  }

  if (pool->blocks && pool->start == pool->blocks->s) {

    BLOCK *temp;

    int blockSize = (int)((unsigned)(pool->end - pool->start)*2U);

    size_t bytesToAllocate;



    /* NOTE: Needs to be calculated prior to calling `realloc`

             to avoid dangling pointers: */

    const ptrdiff_t offsetInsideBlock = pool->ptr - pool->start;



    if (blockSize < 0) {

      /* This condition traps a situation where either more than

       * INT_MAX/2 bytes have already been allocated.  This isn't

       * readily testable, since it is unlikely that an average

       * machine will have that much memory, so we exclude it from the

       * coverage statistics.

       */

      return XML_FALSE; /* LCOV_EXCL_LINE */

    }



    bytesToAllocate = poolBytesToAllocateFor(blockSize);

    if (bytesToAllocate == 0)

      return XML_FALSE;



    temp = (BLOCK *)

      pool->mem->realloc_fcn(pool->blocks, (unsigned)bytesToAllocate);

    if (temp == NULL)

      return XML_FALSE;

    pool->blocks = temp;

    pool->blocks->size = blockSize;

    pool->ptr = pool->blocks->s + offsetInsideBlock;

    pool->start = pool->blocks->s;

    pool->end = pool->start + blockSize;

  }

  else {

    BLOCK *tem;

    int blockSize = (int)(pool->end - pool->start);

    size_t bytesToAllocate;



    if (blockSize < 0) {

      /* This condition traps a situation where either more than

       * INT_MAX bytes have already been allocated (which is prevented

       * by various pieces of program logic, not least this one, never

       * mind the unlikelihood of actually having that much memory) or

       * the pool control fields have been corrupted (which could

       * conceivably happen in an extremely buggy user handler

       * function).  Either way it isn't readily testable, so we

       * exclude it from the coverage statistics.

       */

      return XML_FALSE;  /* LCOV_EXCL_LINE */

    }



    if (blockSize < INIT_BLOCK_SIZE)

      blockSize = INIT_BLOCK_SIZE;

    else {

      /* Detect overflow, avoiding _signed_ overflow undefined behavior */

      if ((int)((unsigned)blockSize * 2U) < 0) {

        return XML_FALSE;

      }

      blockSize *= 2;

    }



    bytesToAllocate = poolBytesToAllocateFor(blockSize);

    if (bytesToAllocate == 0)

      return XML_FALSE;



    tem = (BLOCK *)pool->mem->malloc_fcn(bytesToAllocate);

    if (!tem)

      return XML_FALSE;

    tem->size = blockSize;

    tem->next = pool->blocks;

    pool->blocks = tem;

    if (pool->ptr != pool->start)

      memcpy(tem->s, pool->start,

             (pool->ptr - pool->start) * sizeof(XML_Char));

    pool->ptr = tem->s + (pool->ptr - pool->start);

    pool->start = tem->s;

    pool->end = tem->s + blockSize;

  }

  return XML_TRUE;

}



static int FASTCALL

nextScaffoldPart(XML_Parser parser)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  CONTENT_SCAFFOLD * me;

  int next;



  if (!dtd->scaffIndex) {

    dtd->scaffIndex = (int *)MALLOC(parser, parser->m_groupSize * sizeof(int));

    if (!dtd->scaffIndex)

      return -1;

    dtd->scaffIndex[0] = 0;

  }



  if (dtd->scaffCount >= dtd->scaffSize) {

    CONTENT_SCAFFOLD *temp;

    if (dtd->scaffold) {

      temp = (CONTENT_SCAFFOLD *)

        REALLOC(parser, dtd->scaffold, dtd->scaffSize * 2 * sizeof(CONTENT_SCAFFOLD));

      if (temp == NULL)

        return -1;

      dtd->scaffSize *= 2;

    }

    else {

      temp = (CONTENT_SCAFFOLD *)MALLOC(parser, INIT_SCAFFOLD_ELEMENTS

                                        * sizeof(CONTENT_SCAFFOLD));

      if (temp == NULL)

        return -1;

      dtd->scaffSize = INIT_SCAFFOLD_ELEMENTS;

    }

    dtd->scaffold = temp;

  }

  next = dtd->scaffCount++;

  me = &dtd->scaffold[next];

  if (dtd->scaffLevel) {

    CONTENT_SCAFFOLD *parent = &dtd->scaffold[dtd->scaffIndex[dtd->scaffLevel-1]];

    if (parent->lastchild) {

      dtd->scaffold[parent->lastchild].nextsib = next;

    }

    if (!parent->childcnt)

      parent->firstchild = next;

    parent->lastchild = next;

    parent->childcnt++;

  }

  me->firstchild = me->lastchild = me->childcnt = me->nextsib = 0;

  return next;

}



static void

build_node(XML_Parser parser,

           int src_node,

           XML_Content *dest,

           XML_Content **contpos,

           XML_Char **strpos)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  dest->type = dtd->scaffold[src_node].type;

  dest->quant = dtd->scaffold[src_node].quant;

  if (dest->type == XML_CTYPE_NAME) {

    const XML_Char *src;

    dest->name = *strpos;

    src = dtd->scaffold[src_node].name;

    for (;;) {

      *(*strpos)++ = *src;

      if (!*src)

        break;

      src++;

    }

    dest->numchildren = 0;

    dest->children = NULL;

  }

  else {

    unsigned int i;

    int cn;

    dest->numchildren = dtd->scaffold[src_node].childcnt;

    dest->children = *contpos;

    *contpos += dest->numchildren;

    for (i = 0, cn = dtd->scaffold[src_node].firstchild;

         i < dest->numchildren;

         i++, cn = dtd->scaffold[cn].nextsib) {

      build_node(parser, cn, &(dest->children[i]), contpos, strpos);

    }

    dest->name = NULL;

  }

}



static XML_Content *

build_model (XML_Parser parser)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  XML_Content *ret;

  XML_Content *cpos;

  XML_Char * str;

  int allocsize = (dtd->scaffCount * sizeof(XML_Content)

                   + (dtd->contentStringLen * sizeof(XML_Char)));



  ret = (XML_Content *)MALLOC(parser, allocsize);

  if (!ret)

    return NULL;



  str =  (XML_Char *) (&ret[dtd->scaffCount]);

  cpos = &ret[1];



  build_node(parser, 0, ret, &cpos, &str);

  return ret;

}



static ELEMENT_TYPE *

getElementType(XML_Parser parser,

               const ENCODING *enc,

               const char *ptr,

               const char *end)

{

  DTD * const dtd = parser->m_dtd;  /* save one level of indirection */

  const XML_Char *name = poolStoreString(&dtd->pool, enc, ptr, end);

  ELEMENT_TYPE *ret;



  if (!name)

    return NULL;

  ret = (ELEMENT_TYPE *) lookup(parser, &dtd->elementTypes, name, sizeof(ELEMENT_TYPE));

  if (!ret)

    return NULL;

  if (ret->name != name)

    poolDiscard(&dtd->pool);

  else {

    poolFinish(&dtd->pool);

    if (!setElementTypePrefix(parser, ret))

      return NULL;

  }

  return ret;

}



static XML_Char *

copyString(const XML_Char *s,

           const XML_Memory_Handling_Suite *memsuite)

{

    int charsRequired = 0;

    XML_Char *result;



    /* First determine how long the string is */

    while (s[charsRequired] != 0) {

      charsRequired++;

    }

    /* Include the terminator */

    charsRequired++;



    /* Now allocate space for the copy */

    result = memsuite->malloc_fcn(charsRequired * sizeof(XML_Char));

    if (result == NULL)

        return NULL;

    /* Copy the original into place */

    memcpy(result, s, charsRequired * sizeof(XML_Char));

    return result;

}

